/* LISTENING (second doubling pass, part A) — Conversations vza001-vza029 (student / professor / administration situations) and Academic Talks tza001-tza016 (natural sciences, technology, environment, health) */
(function () {
  CONTENT.conv.push(
    { id: 'vza001', diff: 2, ctx: "Listen to a conversation between a student and an employee at the international student office.", names: { W: "Employee", M: "Student" }, lines: [
      ["M", "Hi, I've been offered a paid internship at a marketing firm downtown, and I wanted to check whether I'm allowed to accept it. I'm here on a student visa."],
      ["W", "I'm glad you checked first, because working without authorization can cause serious problems for your status. Is the internship related to your field of study?"],
      ["M", "Sort of. It's marketing analytics, and I'm majoring in statistics, so there's quite a lot of overlap on the data side."],
      ["W", "That helps. Off-campus work that's part of your degree usually falls under something called curricular practical training. You must have completed one full academic year, and you need a letter from your department."],
      ["M", "I finished my second semester in May, so that should be fine. How long does the letter take?"],
      ["W", "Your academic adviser can usually write it within a few days, but then our office needs about two weeks to process the request. You can't start until you actually hold the new work authorization."],
      ["M", "Two weeks? The firm wants me to begin on the fifteenth, which is only three weeks away."],
      ["W", "That can still work if you submit everything this week. I'd email your adviser today, and I'd tell the firm that your start date depends on the paperwork."],
      ["M", "Right. And if I'm approved, is there a limit on how many hours I can work?"],
      ["W", "During the semester it has to be part-time, so up to twenty hours a week. Full-time is allowed during the summer break."],
      ["M", "That's fine. I'll be in class most days anyway. Thanks for your help."]],
      qs: [
        { q: "Why does the student come to the international student office?", o: ["To renew his visa before the next semester begins", "To ask whether his visa lets him take a paid internship", "To have the office contact the firm about a start date", "To find out whether his department will approve a new major"], a: 1, x: "Il vient vérifier s'il a le droit d'accepter un stage rémunéré avec son visa étudiant." },
        { q: "What does the employee tell the student to do first?", o: ["Pay the processing fee online before the end of this week", "Email his academic adviser to ask for a department letter", "Ask the firm to confirm his hours in a signed contract", "Wait until the summer break begins, then submit his application"], a: 1, x: "Elle conseille d'écrire dès aujourd'hui à son directeur d'études pour obtenir la lettre du département." },
        { q: "Why does the employee suggest telling the firm that his start date depends on the paperwork?", o: ["The firm will probably withdraw the offer if the start date slips", "Her office is usually slower than two weeks in the summer", "He is not legally allowed to start before authorization arrives", "Interns at the firm are paid only after their visa is renewed"], a: 2, x: "Il ne peut pas commencer avant d'avoir l'autorisation de travail : « You can't start until you actually hold the new work authorization »." } ] },
    { id: 'vza002', diff: 2, ctx: "Listen to a conversation between a student and a professor.", names: { M: "Professor", W: "Student" }, lines: [
      ["W", "Professor Kim, do you have a minute? I'm applying to master's programs in public policy, and I was wondering if you'd be willing to write me a letter of recommendation."],
      ["M", "I'd be glad to. You did excellent work in my seminar, and your research project last spring was one of the best I've supervised. When are the applications due?"],
      ["W", "The first one is due on the fifteenth of next month, but the portal asks recommenders to submit their letters a week before that."],
      ["M", "So about three weeks. That's fine, but I'm traveling to a conference next week, so it would help if you sent me everything by Friday."],
      ["W", "Of course. What should I include?"],
      ["M", "Your CV, a draft of your personal statement, and a short list of the courses you took with me, along with your grades. And a sentence or two about each program, so I can tailor the letter. Generic letters don't impress admissions committees."],
      ["W", "Understood. I'm also thinking of asking my former manager from my summer job. Would two letters from such different sides be a problem?"],
      ["M", "Not at all, quite the opposite. I can speak about your analytical skills, and your manager can speak about how you work with other people. Together they give a fuller picture."],
      ["W", "That's reassuring. Thank you so much, Professor."],
      ["M", "My pleasure. Send me the draft statement as soon as you can, and I'll give you some comments on it as well."]],
      qs: [
        { q: "Why does the student visit the professor?", o: ["To ask for help with the research project she completed last spring", "To discuss the grade she received for her seminar paper last term", "To find out which public policy programs he would recommend to her", "To ask him to write a letter for her master's applications"], a: 3, x: "Elle lui demande une lettre de recommandation pour ses candidatures en master." },
        { q: "Why does the professor ask the student to send her materials by Friday?", o: ["The portal closes to recommenders on Friday", "He will be away at a conference next week", "He wants time to reread her seminar paper", "He is writing letters for several other students"], a: 1, x: "Il voyage la semaine prochaine : « I'm traveling to a conference next week »." },
        { q: "What does the professor imply about getting a second letter from her former manager?", o: ["It could make her application look less focused on academic work", "It is unnecessary as long as his own letter is strong enough", "It should be written and sent before his own letter is submitted", "It would give the committees a fuller picture of her abilities"], a: 3, x: "Il dit « quite the opposite » : deux regards différents donnent « a fuller picture »." } ] },
    { id: 'vza003', diff: 2, ctx: "Listen to a conversation between a student and a tutor at the university writing center.", names: { W: "Tutor", M: "Student" }, lines: [
      ["M", "I have a draft of my essay on social media and teenagers, but my instructor wrote 'thesis too broad' at the top, and I honestly don't see what's wrong with it."],
      ["W", "Let's look. Your thesis says, 'Social media has many effects on teenagers.' Hmm. Would anyone disagree with that?"],
      ["M", "I suppose not. It's true, isn't it?"],
      ["W", "It is, and that's the problem. A strong thesis makes a claim that someone could argue against. Right now you've announced a topic, not a position."],
      ["M", "So I should say whether the effects are good or bad?"],
      ["W", "Not necessarily. You could pick one specific effect, such as sleep, and argue that it's the most serious one. That also solves your other problem, which is that you're already over the word limit."],
      ["M", "Oh, I hadn't connected those two. If I focus on sleep, I can cut the paragraphs about online friendships and advertising."],
      ["W", "Exactly. Try this: write your new thesis in one sentence, then look at each paragraph and ask whether it supports that sentence. If not, it goes."],
      ["M", "That sounds painful, but fair. Can I come back on Thursday with a revised version?"],
      ["W", "Absolutely. Book a slot online, and bring the new thesis written on a separate sheet so we can start there."]],
      qs: [
        { q: "What is wrong with the student's thesis, according to the tutor?", o: ["It contains a factual mistake about teenagers", "It is far too long for a single sentence", "It states a topic without taking a position", "It contradicts the examples in his essay"], a: 2, x: "« You've announced a topic, not a position » : personne ne contredirait cette phrase." },
        { q: "How would narrowing the thesis help with the word limit?", o: ["He would be allowed to use shorter quotations in the paragraphs that remain", "He could cut the paragraphs that no longer support his new focus on sleep", "The instructor would be willing to accept a longer essay this time", "He could combine several related paragraphs into one longer paragraph"], a: 1, x: "En se concentrant sur le sommeil, il peut supprimer les paragraphes sur l'amitié en ligne et la publicité." },
        { q: "What will the student probably do next?", o: ["Ask his instructor to approve a different essay topic for the course", "Rewrite his thesis and come back to the writing center on Thursday", "Start the essay again from the beginning with the same thesis", "Add more examples about online friendships and advertising to his draft"], a: 1, x: "Il propose de revenir jeudi avec une version révisée ; la tutrice l'invite à réserver un créneau." } ] },
    { id: 'vza004', diff: 2, ctx: "Listen to a conversation between a student and a laboratory manager.", names: { W: "Lab manager", M: "Student" }, lines: [
      ["M", "Hi, I'd like to book the confocal microscope for next week. My thesis supervisor said I should come to you."],
      ["W", "Sure. Have you been trained on it? You can't book it until you've completed the safety and operating session."],
      ["M", "No, I haven't. When is the next session?"],
      ["W", "They run on Tuesday mornings, and next Tuesday's is already full. The one after that has a couple of places left."],
      ["M", "That's the week of my thesis deadline, though. I was hoping to collect my images before then."],
      ["W", "Then you might ask your supervisor whether a labmate who's already certified could run the first samples with you. That's allowed as long as the certified person stays in the room."],
      ["M", "That's a good idea. Actually, one of the doctoral students in our group has used it for years."],
      ["W", "Perfect. She can make the booking under her name. Slots are two hours each, and you can only reserve two per week, so plan which samples matter most."],
      ["M", "And what if we can't make it?"],
      ["W", "Cancel at least twenty-four hours ahead. Otherwise the slot counts as used, and somebody else loses the chance to book it."],
      ["M", "Understood. I'll talk to her this afternoon."]],
      qs: [
        { q: "What problem does the student have?", o: ["His thesis supervisor has not yet approved the experiments he planned to run", "The microscope is out of order and will not be repaired before his deadline", "He has already used up the two booking slots allowed to him this week", "He must complete training before booking, but no session fits his schedule"], a: 3, x: "Il n'est pas formé, et la prochaine session libre tombe la semaine de la date limite." },
        { q: "What does the lab manager suggest?", o: ["Working with a certified labmate who stays in the room all the time", "Asking his supervisor to move the thesis deadline to a later date", "Skipping the training session if his supervisor agrees to supervise him", "Using a different microscope in another building that needs no training"], a: 0, x: "Un collègue certifié peut réserver et rester présent pendant les premières mesures." },
        { q: "Why does the lab manager mention cancelling twenty-four hours ahead?", o: ["Users who cancel after that time are charged a fee for the slot", "Late cancellations take slots away from other people", "The microscope needs a full day to warm up before it is used", "Training sessions are held only on Tuesdays and fill up quickly"], a: 1, x: "Un créneau annulé trop tard est compté comme utilisé, et un autre étudiant perd l'occasion de réserver." } ] },
    { id: 'vza005', diff: 2, ctx: "Listen to a conversation between a student and an employee at the campus parking office.", names: { M: "Employee", W: "Student" }, lines: [
      ["W", "Hello, I got a parking ticket last Thursday and I think it was a mistake. It says I parked in Lot B without a Lot B permit."],
      ["M", "Do you have a permit for a different lot?"],
      ["W", "Yes, Lot C. But Lot C was closed that week for construction. I got an email from the parking office telling us to use Lot B temporarily."],
      ["M", "Ah, I see. Was that email sent to all permit holders?"],
      ["W", "I believe so. I can show it to you on my phone. It says Lot C permits are valid in Lot B until the end of the month."],
      ["M", "Yes, that's the notice we sent. Unfortunately, the officers were not all informed about it, and tickets did go out by mistake. The ticket was sixty dollars, correct?"],
      ["W", "That's right. Do I have to pay it first and then ask for a refund?"],
      ["M", "No, you don't. Fill out this appeal form, attach a copy of the email, and the fine will be put on hold. You should hear back within ten working days."],
      ["W", "Great. Is there anything else I should do?"],
      ["M", "Just keep your permit visible on the dashboard. If you get another ticket in the meantime, bring it to us right away."]],
      qs: [
        { q: "Why does the student believe her ticket was a mistake?", o: ["She was told by email that Lot C permits were valid in Lot B", "She had bought a temporary permit for Lot B at the parking office", "She had parked in Lot B for less than an hour while she was in class", "Her permit was clearly visible on the dashboard of her car"], a: 0, x: "Un e-mail du bureau du stationnement autorisait les permis du parking C dans le parking B." },
        { q: "According to the employee, why were tickets issued by mistake?", o: ["The notice was sent to the wrong group of students", "The construction work ended earlier than the office had planned it to", "The permit system had listed incorrect lot numbers for some drivers", "Some officers were never told about the arrangement"], a: 3, x: "« The officers were not all informed about it »." },
        { q: "What does the employee tell the student to do?", o: ["Pay the fine and wait for a refund", "Move her car to Lot C immediately", "Come back in ten working days with a new permit", "Submit an appeal form with a copy of the email"], a: 3, x: "Remplir le formulaire d'appel et joindre l'e-mail ; l'amende est suspendue." } ] },
    { id: 'vza006', diff: 2, ctx: "Listen to a conversation between a student and a disability services coordinator.", names: { W: "Coordinator", M: "Student" }, lines: [
      ["M", "Hi, I was diagnosed with ADHD last year, and I'd like to know what kind of support the university offers. I struggled a lot in the exams last semester."],
      ["W", "I'm sorry to hear that, but I'm glad you came. Do you have documentation of the diagnosis?"],
      ["M", "I have a report from my doctor. It's about two pages."],
      ["W", "That should be enough. If it's accepted, you'd typically be offered extra time on exams, say fifty percent more, and the option to sit them in a quiet room."],
      ["M", "That would really help. I tend to lose focus when other people are moving around. But I don't want my professors to know about my diagnosis."],
      ["W", "They won't. We send each professor an accommodation letter that lists only what you're entitled to, never the reason. And whatever you tell us stays confidential."],
      ["M", "Okay, that's a relief. Do I need to do anything every semester?"],
      ["W", "Yes, you request the letters again for each course. And for every exam, you book a seat at the testing center at least three days ahead, because the rooms are limited."],
      ["M", "Three days. I'll write that in my calendar. How long until I know if I'm approved?"],
      ["W", "Usually about a week. I'll email you as soon as the committee has reviewed your report."]],
      qs: [
        { q: "Why does the student come to the disability services office?", o: ["To get his doctor's report translated", "To appeal a grade he received last semester", "To find out what help he can get for exams", "To ask for a different course schedule"], a: 2, x: "Il a eu des difficultés aux examens et veut connaître l'aide proposée." },
        { q: "What worry does the student express about his professors?", o: ["They might find out that he has a diagnosed condition", "They might refuse to give him the extra time he needs", "They might forget to read the accommodation letter in time", "They might change the dates of the exams without telling him"], a: 0, x: "« I don't want my professors to know about my diagnosis »." },
        { q: "What can be inferred about the testing center?", o: ["It is open only during the final exam period of each semester", "Its rooms are limited, so students have to book several days ahead", "Professors choose which of their students may use its rooms", "It charges students a small fee for each extra hour of time"], a: 1, x: "Il faut réserver trois jours à l'avance « because the rooms are limited »." } ] },
    { id: 'vza007', diff: 3, ctx: "Listen to a conversation between a student and a professor.", names: { M: "Professor", W: "Student" }, lines: [
      ["W", "Professor Reyes, I wanted to talk to you about our group project, because, well, it's not going great. One of my teammates hasn't done anything. He didn't come to the last two meetings, and the section he promised still doesn't exist."],
      ["M", "I'm sorry to hear that. Have you spoken to him directly?"],
      ["W", "I messaged him twice. The first time he said he was swamped, and the second time he just didn't reply."],
      ["M", "Hm. Okay. So what would you like me to do?"],
      ["W", "Honestly, I'd like him not to get the same grade as the three of us who've been doing the work. It doesn't seem fair."],
      ["M", "I understand why you feel that way, but I'm not going to adjust anyone's grade on the strength of one conversation. That wouldn't be fair to him either, would it?"],
      ["W", "No, I suppose not. I just thought you'd want to know."],
      ["M", "And I do. That's why there's a peer evaluation form at the end of the project, where each of you rates everyone's contribution. If the ratings differ sharply, I take it into account. But the form is only as useful as the evidence behind it."],
      ["W", "So you're saying I should keep records."],
      ["M", "I'm saying it can't hurt. Save the messages, note who was assigned what, and who delivered it. And before the deadline, send him one clear email with a date for his section, copying me in. If he still doesn't deliver, we'll have something concrete to look at."],
      ["W", "Okay. I was worried you'd think I was just complaining."],
      ["M", "Not at all. Just keep it factual, and don't make it sound like it's three against one."]],
      qs: [
        { q: "Why does the student go to see the professor?", o: ["To report that one team member is not contributing", "To ask for a different group for the rest of the course", "To request an extension for the whole group", "To complain that the assignment was unclear"], a: 0, x: "Un coéquipier n'a rien fait, et elle veut que le professeur le sache." },
        { q: "How does the professor respond to the student's wish that the teammate get a lower grade?", o: ["He agrees to lower the teammate's grade immediately if she signs a complaint", "He promises to lower the grade if the teammate misses another meeting", "He tells her the grade will be the same for everyone no matter what", "He says a peer evaluation will take each person's contribution into account"], a: 3, x: "Il ne modifie pas de note sur une seule conversation, mais le formulaire d'évaluation par les pairs permet de tenir compte des écarts." },
        { q: "What does the professor mean when he says, \"Just keep it factual, and don't make it sound like it's three against one\"?", o: ["She should avoid discussing the problem with the other members of the team", "She should ask the other two students to sign a written complaint with her", "She should assume that the teammate has a good reason for his silence", "She should describe it as a team problem and not as a personal conflict"], a: 3, x: "Il lui conseille de s'en tenir aux faits et d'éviter de présenter la situation comme un conflit personnel d'un camp contre un autre." } ] },
    { id: 'vza008', diff: 3, ctx: "Listen to a conversation between a master's student and her thesis supervisor.", names: { W: "Supervisor", M: "Student" }, lines: [
      ["M", "So, I finished running the analysis over the weekend, and, um, I'm afraid it isn't what we hoped. The financial literacy workshop made no measurable difference to how much the participants saved."],
      ["W", "No difference at all?"],
      ["M", "The treatment group saved slightly more, but the gap is well within the margin of error. Basically, there's nothing there. I feel like I've wasted a year."],
      ["W", "Let's not get dramatic. A well-designed study that finds no effect is still a finding, and a useful one, especially if previous work suggested the opposite."],
      ["M", "But no one gives a master's degree for a result that says nothing happened."],
      ["W", "They do if the thesis explains why. Think about what you can say. Was the sample large enough? How long after the workshop did you measure savings? Were participants already saving a lot, so there was no room for improvement?"],
      ["M", "I could look at subgroups. Maybe the workshop helped people with lower incomes, and the effect cancels out when everyone is averaged together."],
      ["W", "You can look, but I'd be careful. If you slice the data into enough pieces, something will always look significant by chance. Whatever you test, decide on it now, and say so openly in the thesis."],
      ["M", "So I report it as exploratory."],
      ["W", "Exactly. Report it, label it for what it is, and let the reader decide how much weight to put on it. That's honesty, not failure."],
      ["M", "Okay. I think I'd been treating the null result like something I had to hide."],
      ["W", "Well, you shouldn't. Hiding it is the only thing that would actually make this a bad thesis."]],
      qs: [
        { q: "What is the student mainly worried about?", o: ["His results might not be enough to earn a master's degree", "The workshop may have been too short to show any effect", "His sample may be too small for the results to count", "He may have made an error in his data analysis"], a: 0, x: "Il craint qu'un résultat nul ne vaille pas un diplôme : « no one gives a master's degree for a result that says nothing happened »." },
        { q: "Why is the supervisor cautious about the idea of looking at subgroups?", o: ["The workshop was designed for participants from a single income group", "Splitting the data into many pieces produces false positives", "The department does not allow exploratory analysis in a master's thesis", "Subgroup analysis would take too long before the thesis deadline"], a: 1, x: "En découpant les données en assez de sous-groupes, quelque chose paraîtra toujours significatif par hasard." },
        { q: "What does the supervisor imply in her final comment?", o: ["A thesis is weakest when it hides unwelcome results", "The student should have chosen a different topic", "The committee will probably ignore the null result", "The student should rewrite his hypothesis to fit the data"], a: 0, x: "Cacher le résultat serait la seule chose qui ferait vraiment un mauvais mémoire : l'honnêteté prime sur le résultat." } ] },
    { id: 'vza009', diff: 3, ctx: "Listen to a conversation between a student and a department chair.", names: { M: "Chair", W: "Student" }, lines: [
      ["W", "Professor Anders, I just got an email saying that Advanced Econometrics has been cancelled. I need it to graduate in May."],
      ["M", "Yes, I'm afraid that's right. It had seven students enrolled, and the dean's office won't run a graduate course with fewer than ten. It wasn't my decision, if that helps."],
      ["W", "It doesn't, really. Is there any chance of reversing it? I could ask the other six to write letters, if that would make a difference."],
      ["M", "I admire the initiative, but my hands are somewhat tied. The dean's office applies that rule across the board, and I'd rather not spend my goodwill on a fight I know I'll lose."],
      ["W", "Then what are my options?"],
      ["M", "There are two. You can petition to substitute another course from the approved list, but the committee only meets in March, which is cutting it fine. The other possibility is an independent study. One of our faculty would supervise you through the same material, with a reading list and a final paper."],
      ["W", "An independent study sounds like more work than the course itself."],
      ["M", "It can be, though some students find it more rewarding, since you're working one-on-one. But you'd need a faculty sponsor and a one-page syllabus by next Friday, which is the registration cutoff."],
      ["W", "Next Friday. Do you know anyone who might agree?"],
      ["M", "Professor Lindqvist teaches the econometrics sequence, and she's mentioned that she'd like to take on more graduate advising. I'd start there. Mention that I sent you."]],
      qs: [
        { q: "Why was the course cancelled?", o: ["Too few students had enrolled to meet the dean's minimum", "The professor who was going to teach it left the university", "The dean's office reduced the department's budget", "The students did not complete the prerequisite course"], a: 0, x: "Sept inscrits seulement ; le décanat n'ouvre pas de cours de master avec moins de dix étudiants." },
        { q: "What does the chair mean when he says, \"my hands are somewhat tied\"?", o: ["He is too busy to help her at the moment", "He believes the other students will not support her", "He disagrees with the dean's office policy", "He has little power to change the decision"], a: 3, x: "Il n'a guère la marge de manoeuvre pour renverser une règle appliquée partout par le décanat." },
        { q: "What is a drawback of the petition option?", o: ["It costs more than a regular course", "It requires the signatures of six students", "The committee may not decide in time", "It cannot be used for graduate courses"], a: 2, x: "Le comité ne se réunit qu'en mars : « cutting it fine »." } ] },
    { id: 'vza010', diff: 3, ctx: "Listen to a conversation between a student and an academic integrity officer.", names: { W: "Officer", M: "Student" }, lines: [
      ["W", "Thanks for coming in, David. I should say right away that this isn't a disciplinary hearing. I'd just like to talk about the report that came back on your marketing paper."],
      ["M", "Yeah, I saw there was a notification. It said thirty-eight percent similarity. But I didn't copy anything from anyone."],
      ["W", "I believe you. The software matched several paragraphs to a paper submitted last year, and the author of that paper is you."],
      ["M", "Right. I wrote about the same company in my first-year course, so I reused some of my own analysis. It's my work. How can I plagiarize myself?"],
      ["W", "That's the question everyone asks. The policy treats it as duplicate submission. Unless the instructor approves it in advance, you can't earn credit twice for the same work."],
      ["M", "Nobody told me that. I thought it was only a problem if you used other people's ideas."],
      ["W", "It's in the syllabus, but I'll admit it's buried on page eleven. That's partly why I'm taking an educational approach this time."],
      ["M", "What does that mean in practice?"],
      ["W", "You rewrite the affected sections with new analysis and resubmit within a week. Your instructor will grade the paper as if it had come in on time, minus a small penalty. And there'll be a note in your file, though not a formal sanction."],
      ["M", "And if it happens again?"],
      ["W", "Then it's a different conversation, and I'd rather we never have it."],
      ["M", "Understood. I'll start on the rewrite tonight."]],
      qs: [
        { q: "What is the main purpose of the meeting?", o: ["To punish the student for copying a paper written by another student", "To ask the student to withdraw from his marketing course this term", "To teach the student how to cite his sources correctly in future papers", "To explain why the software flagged his paper and what happens next"], a: 3, x: "Le logiciel a repéré des paragraphes identiques à un travail précédent de l'étudiant lui-même : la rencontre sert à expliquer cela et à régler la situation." },
        { q: "What is the student's main objection?", o: ["He says the software report has matched the wrong papers together", "He believes he is free to reuse his own earlier work", "He thinks the instructor misread several pages of his paper", "He claims that another student copied his analysis from last year"], a: 1, x: "« It's my work. How can I plagiarize myself? »" },
        { q: "Why does the officer mention that the rule is on page eleven of the syllabus?", o: ["To admit that the rule is not easy for students to notice", "To suggest that the student should have read it more carefully", "To show that the policy was introduced recently", "To prove that the instructor ignored the policy"], a: 0, x: "Elle reconnaît que la règle est « buried on page eleven » : cela explique son approche pédagogique plutôt que sanctionnante." } ] },
    { id: 'vza011', diff: 3, ctx: "Listen to a conversation between a student and the chair of a scholarship committee.", names: { M: "Chair", W: "Student" }, lines: [
      ["W", "Thanks for seeing me. I got the letter about my scholarship renewal, and I'm a little confused. It says my GPA is three point four two, and that I'm being renewed on probation."],
      ["M", "That's right. The scholarship requires a three point five, and you fell just short. Rather than cancel it, the committee renews it for one more semester, and if you're back above the line by then, the probation is lifted."],
      ["W", "I understand the rule. It's just that most of the drop came from one course, organic chemistry, which was brutal for everybody. The class average was a C-minus."],
      ["M", "I've heard that. It's a hard course."],
      ["W", "So I was wondering whether I could appeal, and ask that the course be treated differently for the GPA requirement."],
      ["M", "You can appeal, but I'd be honest with you about the odds. The committee doesn't adjust the number for individual courses. If it did, nearly everyone would have a course they'd want excluded."],
      ["W", "I see. So there's no point in appealing."],
      ["M", "I didn't say that. What the committee does look at is trajectory. If you wrote a short letter explaining the circumstances, and your grades in other courses were rising, that could make a difference for the later review."],
      ["W", "So the real goal is to get above three point five this semester."],
      ["M", "Precisely. A second probation is possible, but it's rare, and I wouldn't plan around it."],
      ["W", "Okay. Thank you for being straightforward with me."]],
      qs: [
        { q: "Why is the student's scholarship being renewed on probation?", o: ["Her GPA of three point four two is just under the required level", "She missed the deadline for submitting the renewal form", "She failed a course in organic chemistry last semester", "Her class average was lower than the scholarship expected"], a: 0, x: "Son GPA de 3,42 est juste sous le seuil de 3,5." },
        { q: "What does the chair say about the appeal?", o: ["It would succeed because the chemistry class was unusually difficult", "It must be submitted before the semester begins", "It would not change the committee's rule on the GPA number", "It requires a letter from her chemistry professor"], a: 2, x: "Le comité n'ajuste pas le chiffre pour des cours individuels, mais regarde la trajectoire." },
        { q: "What does the chair imply when he says, \"A second probation is possible, but it's rare, and I wouldn't plan around it\"?", o: ["She will almost certainly receive another chance", "She should not count on being given a second chance", "The committee never grants a second probation", "He plans to recommend her for a second probation"], a: 1, x: "Possible mais rare : mieux vaut viser un GPA de 3,5 dès ce semestre." } ] },
    { id: 'vza012', diff: 3, ctx: "Listen to a conversation between a student and a registrar's office employee.", names: { W: "Employee", M: "Student" }, lines: [
      ["M", "Hi, I'm trying to order an official transcript to send with a transfer application, but the system says there's a hold on my account."],
      ["W", "Let me look. Okay, yes, there's a financial hold. You have a forty-two dollar library charge for an unreturned book."],
      ["M", "But I returned that book in March. I remember putting it in the drop box outside."],
      ["W", "The library has it listed as lost. Drop box returns are sometimes scanned late, or not at all, when they're stuck behind other books."],
      ["M", "Great. The application is due Monday. Can you just release the hold so I can order the transcript?"],
      ["W", "I'm afraid I can't. Only the office that placed the hold can lift it, and the library doesn't answer to us."],
      ["M", "So I'm supposed to just miss my deadline over a book I already returned?"],
      ["W", "Not necessarily. If you pay the forty-two dollars online, the hold usually clears within a day. Then you can order an electronic transcript, which is sent to the other university within hours."],
      ["M", "But that means admitting I lost it, doesn't it?"],
      ["W", "Not really. Paying is just how you clear the account. Afterwards you can file a claim at the library saying you returned the book, and if they find it, the charge is refunded."],
      ["M", "Hmm. So pay now, argue later."],
      ["W", "If Monday matters most, I'd say yes."]],
      qs: [
        { q: "What is the student's problem?", o: ["His official transcript was sent to the wrong university last week", "He must pay a late fee before his transfer application is accepted", "A financial hold on his account blocks his transcript order", "The library cannot find the book that he wants to borrow"], a: 2, x: "Un blocage financier l'empêche de commander son relevé de notes." },
        { q: "Why can the employee not remove the hold herself?", o: ["The student has not yet filed a claim", "The hold belongs to a different office", "The registrar's office is closed on weekends", "Transcript orders are processed only by the library"], a: 1, x: "Seul le service qui a posé le blocage peut le lever." },
        { q: "What does the employee imply with her last comment?", o: ["Paying now makes sense if the deadline matters most", "The student's argument with the library is unlikely to succeed", "The student should not trust the library's records of returned books", "The student must admit he lost the book before he can complain"], a: 0, x: "« If Monday matters most, I'd say yes » : payer d'abord, contester ensuite, si la date limite prime." } ] },
    { id: 'vza013', diff: 3, ctx: "Listen to a conversation between a student and a professor.", names: { W: "Professor", M: "Student" }, lines: [
      ["M", "Professor Walsh, I wanted to ask about the term paper. It's due on Friday, and I'm not going to be able to finish it. My grandfather passed away last week and I had to travel home for the funeral."],
      ["W", "I'm very sorry for your loss. Take a moment. Do you need anything from me, apart from time?"],
      ["M", "Thank you. I'd really appreciate an extension. I was thinking about three weeks, so I could get my head straight and do it properly."],
      ["W", "Three weeks is longer than I can offer. If I give one student that much, I have to be prepared to give it to everyone with a legitimate reason, and the grades are due at the end of the month."],
      ["M", "I understand. What could you offer?"],
      ["W", "I can give you until a week from Friday, and I'd ask for a one-page outline by this Friday, just so I can see that the paper is moving. That way I know what's finished and what isn't."],
      ["M", "Okay. And if I still can't finish it by then?"],
      ["W", "Then there's the option of an incomplete. It gives you extra time, but it stays on your record as unresolved, and if you don't complete it within a year, it turns into a failing grade."],
      ["M", "A year is a long time to have something hanging over me."],
      ["W", "It is, which is why I'd advise against it unless it's truly necessary. Let's try the shorter extension and see how you feel in a week."],
      ["M", "That's fair. Thank you for being so understanding."],
      ["W", "Of course. And please look after yourself in the meantime."]],
      qs: [
        { q: "Why does the student want an extension?", o: ["He was ill and could not attend several lectures", "He lost part of his paper when his computer failed", "He has been dealing with a family bereavement", "He needs more time to research his topic"], a: 2, x: "Son grand-père est décédé et il est rentré pour les funérailles." },
        { q: "Why does the professor refuse the three-week extension?", o: ["The student has already received an extension earlier in the same term", "The paper is too important to the final grade to be delayed that long", "The university does not permit extensions for reasons involving family", "It would be unfair to others and conflict with the grading deadline"], a: 3, x: "Elle devrait l'accorder à tous ceux qui ont une raison légitime, et les notes sont dues à la fin du mois." },
        { q: "What can be inferred about the professor's attitude toward the incomplete?", o: ["She considers it the best available solution for his situation", "She believes it will protect his grade permanently from penalties", "She thinks he should have asked for it several weeks earlier", "She would rather he avoided it unless he has no other choice"], a: 3, x: "Elle déconseille cette option sauf nécessité : elle reste non résolue et devient un échec après un an." } ] },
    { id: 'vza014', diff: 3, ctx: "Listen to a conversation between a student and an academic advisor.", names: { W: "Advisor", M: "Student" }, lines: [
      ["M", "I wanted to ask about adding philosophy as a second major. I'm already doing economics, but I keep finding the philosophy electives more interesting than my core courses."],
      ["W", "That's not unusual, and it combines well. Have you looked at what the double major would involve?"],
      ["M", "Roughly. I think it's about nine extra courses, which I could fit in if I take five per semester."],
      ["W", "Five per semester, every semester, for the next two years. And economics majors tend to have the heavy quantitative courses in the same terms as the upper-level seminars."],
      ["M", "I know it'll be demanding, but I'm sure I can handle it."],
      ["W", "Everyone says that in October."],
      ["M", "Ha, fair enough. But I mean it. I did four courses plus a part-time job last year and kept a three point eight."],
      ["W", "And I don't doubt it. What I'm wondering is what you'd give up. There's no room left for study abroad, and not much for the internship you mentioned last month."],
      ["M", "Hm. I hadn't thought about the internship. That does matter, especially for finance."],
      ["W", "A minor in philosophy is five courses instead of nine. You'd read the same authors, but you'd keep your summers and a semester abroad free."],
      ["M", "So you're saying the minor is the smarter choice."],
      ["W", "I'm saying the major isn't wrong, just expensive. You don't have to declare until the end of the semester, so go to a couple of upper-level philosophy classes first, and see whether the enthusiasm survives the reading load."]],
      qs: [
        { q: "What is the student considering?", o: ["Switching from economics to philosophy", "Replacing his core courses with electives", "Studying philosophy abroad next year", "Adding a second major to his current one"], a: 3, x: "Il veut ajouter la philosophie comme deuxième majeure en plus de l'économie." },
        { q: "What does the advisor imply when she says, \"Everyone says that in October\"?", o: ["Students usually change their minds before the end of October", "Students often underestimate how heavy their workload will become", "Students normally apply for a double major in the fall semester", "Students become more confident about their courses as the term goes on"], a: 1, x: "Ironie : tout le monde se dit capable en octobre, puis la charge de travail se fait sentir plus tard." },
        { q: "Why does the advisor mention the internship and study abroad?", o: ["To suggest that he should apply for both of them right away", "To show that both of them are required for the economics major", "To point out that a double major leaves little room for them", "To argue that philosophy students rarely manage to find internships"], a: 2, x: "Le double cursus ne laisserait presque pas de place pour un stage ou un séjour à l'étranger." } ] },
    { id: 'vza015', diff: 3, ctx: "Listen to a conversation between a professor and a student during office hours.", names: { M: "Professor", W: "Student" }, lines: [
      ["M", "Come in, come in. I've read your proposal for the term paper. It's, um, very ambitious."],
      ["W", "Thank you. I wanted to compare how five different countries handled their banking crises after 2008."],
      ["M", "Yes, I saw that. Five countries, three policy tools each, and a theoretical framework on top. In twenty-five pages."],
      ["W", "Is that too much?"],
      ["M", "Let me put it this way. If you had a hundred pages, I'd be thrilled. At twenty-five, I suspect you'd spend three pages on each country and have nothing left for analysis."],
      ["W", "I thought a broader sample would make the argument stronger."],
      ["M", "It can, but only if you have room to show your reasoning. Otherwise a wide sample just gives you wide, shallow description. What is the question you're really asking?"],
      ["W", "Whether countries that acted quickly recovered faster."],
      ["M", "Then you don't need five cases. Pick two that acted quickly and two that were slow, but similar in other respects, and compare them in depth. That would be a tighter design and a more convincing paper."],
      ["W", "I'm reluctant to cut Ireland. It's the example I find most interesting."],
      ["M", "Then keep Ireland and drop the ones you find least interesting. Your enthusiasm will show in the writing. Send me a revised outline by Monday, and we'll see where you stand."]],
      qs: [
        { q: "What is the professor's main concern about the proposal?", o: ["It tries to cover too much ground for a twenty-five page paper", "Its topic has already been studied far too often by other students", "It lacks a clear theoretical framework to organize the cases", "Its research question is too narrow to fill twenty-five pages"], a: 0, x: "Cinq pays, trois instruments chacun et un cadre théorique en vingt-cinq pages : trop large." },
        { q: "What does the professor imply by calling the proposal \"very ambitious\"?", o: ["He thinks the student is likely to write an exceptional paper", "He is not convinced the plan is realistic for this paper", "He hopes the student will make it even longer", "He believes the student has chosen an easy topic"], a: 1, x: "« Ambitious » est ici un euphémisme poli : le projet n'est pas réaliste dans cette longueur." },
        { q: "What does the professor recommend?", o: ["Writing about Ireland alone and leaving out the other countries", "Increasing the page limit with his own permission for this paper", "Dropping the theoretical framework and focusing on description instead", "Choosing a smaller number of cases and analyzing each one in depth"], a: 3, x: "Deux cas rapides et deux lents, comparés en profondeur." } ] },
    { id: 'vza016', diff: 3, ctx: "Listen to a conversation between a student and a professor about an exam grade.", names: { W: "Professor", M: "Student" }, lines: [
      ["M", "Professor Cho, I looked at my midterm, and I think question four was marked too harshly. I lost eight points, and I really think my answer was right."],
      ["W", "Let's see. Hmm. You solved for the equilibrium price correctly, but you didn't explain how you got there. The question did ask you to justify each step."],
      ["M", "I know, but the number is right. Surely the result matters more than the explanation?"],
      ["W", "In this course, the reasoning is what the points are for. A correct number with no justification could be a lucky guess."],
      ["M", "Okay, but I'd like to submit a regrade request anyway. What's the procedure?"],
      ["W", "You fill out the form on the course page by Friday. But I should tell you something first. When I regrade, I review the entire exam, not only the question you're disputing."],
      ["M", "The whole exam? So my grade could go down?"],
      ["W", "It could. It rarely does, but I once found two errors I'd missed the first time, and the student ended up with a lower score."],
      ["M", "I see. I wasn't expecting that."],
      ["W", "I'm not trying to talk you out of it. If you think you're right, you're entitled to ask. I just want you to decide with the full picture."],
      ["M", "Would you tell me what the other points were, then, if I'm thinking about it?"],
      ["W", "I can show you the marked exam right now. Take ten minutes with it and decide afterwards. There's no pressure."]],
      qs: [
        { q: "Why did the student lose points on question four?", o: ["His final answer for the equilibrium price was incorrect", "He did not finish the question before time ran out", "He did not explain the steps behind his answer", "He misunderstood what the question was asking him to do"], a: 2, x: "Le prix d'équilibre était correct, mais il n'a pas justifié chaque étape." },
        { q: "Why does the professor tell the student about regrading the entire exam?", o: ["To discourage him from submitting a request at all", "To make sure he understands the risk before he decides", "To warn him that the deadline for requests has already passed", "To explain why she is equally strict with every student"], a: 1, x: "« I just want you to decide with the full picture »." },
        { q: "What does the professor offer at the end?", o: ["To raise his grade on that question by two points", "To let him look over his marked exam before he decides", "To answer any further questions he has by email", "To let him retake the question later in her office"], a: 1, x: "Elle lui propose de relire sa copie dix minutes avant de décider." } ] },
    { id: 'vza017', diff: 3, ctx: "Listen to a conversation between a graduate student and a research ethics board administrator.", names: { W: "Administrator", M: "Student" }, lines: [
      ["M", "Hi, I'm a master's student in psychology, and I'm planning a survey on stress among first-year students. I understand I need approval from the ethics board before I start."],
      ["W", "That's right. Any research involving human participants has to be reviewed. Have you filled out the application?"],
      ["M", "I've done a draft. One thing I wanted to ask is whether I can collect students' names. I'd like to follow up with the same people in the spring."],
      ["W", "You can, but it changes the type of review. If responses are anonymous, your study may qualify for an expedited review, which takes about two weeks. If you collect names, it's full review, and that can take six."],
      ["M", "Six weeks? My supervisor and I were counting on starting data collection in four."],
      ["W", "Then consider whether you really need names. Could participants create a code instead, something only they can reproduce, like the initials of their mother and their birth month?"],
      ["M", "Oh, that's clever. We'd match the surveys without knowing who anyone is."],
      ["W", "Right, and it makes the consent form simpler too. But you'd still need to state clearly that participation is voluntary and that they can withdraw."],
      ["M", "Of course. Actually, I was also thinking I could run a small pilot with friends before approval, just to test the questions. Nothing official."],
      ["W", "I'd strongly advise against that. If you collect any data you intend to use, it has to be approved first. A pilot is still data."],
      ["M", "Okay, I didn't realize. I'll wait."],
      ["W", "Good. Revise the application with the code system and submit it this week. If it's complete, you'll very likely make your timeline."]],
      qs: [
        { q: "Why is the student speaking with the administrator?", o: ["To recruit participants for a research study on stress", "To report a problem with a consent form he has used", "To find out how to get ethics approval for his survey", "To ask for funding to cover the costs of his project"], a: 2, x: "Il doit obtenir l'accord du comité d'éthique avant de lancer son enquête." },
        { q: "Why does the administrator suggest a participant code?", o: ["It will make the survey shorter and easier for participants", "It lets him follow up with people without learning who they are", "It is required by the board for all surveys about stress", "It guarantees that the board will approve the survey at once"], a: 1, x: "Un code permet d'apparier les questionnaires sans connaître l'identité des participants, donc une procédure plus rapide." },
        { q: "How does the administrator react to the idea of a pilot with friends?", o: ["She firmly discourages it until the study is approved", "She considers it a good way to save time", "She says it is acceptable if the friends sign consent forms", "She suggests it should be done after the survey"], a: 0, x: "« A pilot is still data » : il faut l'approbation avant de collecter quoi que ce soit." } ] },
    { id: 'vza018', diff: 3, ctx: "Listen to a conversation between a doctoral student and a graduate school administrator.", names: { M: "Student", W: "Administrator" }, lines: [
      ["M", "Hello, I got a message that my fellowship ends in May, and I'm trying to understand what happens to my funding after that."],
      ["W", "Let me pull up your file. Okay. You're in your third year. The fellowship covers three years, and after that funding is normally the responsibility of the department or your supervisor's grant."],
      ["M", "My supervisor's grant is up for renewal, but the decision doesn't come until September. So there's a gap, May through August, and then I don't know what."],
      ["W", "That's more common than you'd think. There are a few things to consider. The department sometimes offers teaching assistantships, and there's also a bridge fund for students who are waiting on a grant decision."],
      ["M", "How does the bridge fund work?"],
      ["W", "It covers your stipend for up to three months, provided your supervisor confirms in writing that a renewal application is pending. It isn't automatic, though. Applications close on the first of April."],
      ["M", "And the teaching assistantships? Could I get one for the fall, in case the grant isn't renewed?"],
      ["W", "I wouldn't count on it. Assignments are released in July, and priority goes to students with no other source of funding. If the grant comes through, you'd be at the end of the line."],
      ["M", "So the safest plan is to apply for the bridge fund now."],
      ["W", "That's my advice. And ask your supervisor, today if possible, whether the grant has any chance of being delayed beyond September. If so, the dean's office might extend the bridge by a month."],
      ["M", "Thank you. This is a lot clearer than what I understood."]],
      qs: [
        { q: "What is the student's main concern?", o: ["His supervisor is planning to leave the university", "He does not qualify for a fellowship", "He may not have funding between May and September", "His teaching duties are interfering with his research"], a: 2, x: "La bourse se termine en mai et la décision sur la subvention n'arrive qu'en septembre." },
        { q: "What condition must be met to receive money from the bridge fund?", o: ["A written note from the supervisor must say a renewal is pending", "The student must have completed his third year of study", "The student must agree to teach at least one course", "The dean's office must approve the application before April"], a: 0, x: "Le directeur doit confirmer par écrit qu'une demande de renouvellement est en cours." },
        { q: "What does the administrator mean when she says, \"I wouldn't count on it\"?", o: ["The bridge fund will probably run out of money before April", "A teaching assistantship is unlikely to be offered to him", "The grant will almost certainly be renewed before the summer ends", "The student is unlikely to meet the deadline for applications"], a: 1, x: "Les postes sont attribués en priorité à ceux qui n'ont pas d'autre financement." } ] },
    { id: 'vza019', diff: 3, ctx: "Listen to a conversation between a student and a professor about a conference abstract.", names: { W: "Professor", M: "Student" }, lines: [
      ["M", "Professor Alvarez, I've drafted an abstract for the spring conference, based on the data I analyzed in your lab this year. I was planning to submit it by myself, but one of the other students said I should check with you."],
      ["W", "I'm glad you did. First, congratulations. I think the work is good enough to present. Now, who else was involved in the project?"],
      ["M", "Well, I ran the analysis and wrote most of the text. But the data collection was done before I joined, by Dr. Park, and you designed the original study."],
      ["W", "Right. So the abstract can't be submitted under your name alone. In our field, anyone who made a substantial contribution to the design, the data or the interpretation should be listed as an author."],
      ["M", "I see. I guess I was worried that having three names would make it look like it was less my work."],
      ["W", "Understandable, but it doesn't work that way. Order matters. The person who did the most work is first author, and that would be you. People reading the program will see that."],
      ["M", "So I'd be first, then Dr. Park, then you?"],
      ["W", "Probably. I'd talk to Dr. Park about it, though, rather than assume. She might want to be second, or she might decline authorship altogether."],
      ["M", "Should I contact her?"],
      ["W", "Yes, and send her the abstract. It's good practice to let coauthors see anything that goes out with their names on it."],
      ["M", "Okay. I'll email her this afternoon and send you both the draft."]],
      qs: [
        { q: "What does the student originally plan to do?", o: ["Present the abstract with the whole research team", "Ask the professor to write the abstract for him", "Withdraw from the conference", "Submit the abstract under his name only"], a: 3, x: "« I was planning to submit it by myself »." },
        { q: "Why does the professor say the abstract cannot be submitted under the student's name alone?", o: ["Students are not allowed to present their work at conferences", "The conference only accepts papers submitted by research teams", "Others made substantial contributions to the design and the data", "She wants her own name to appear first on the abstract"], a: 2, x: "Dr Park a collecté les données et la professeure a conçu l'étude : ce sont des contributions substantielles." },
        { q: "What does the professor suggest about authorship order?", o: ["The student would be listed last as a courtesy to his professors", "Names appear in alphabetical order at this conference", "The student, who did most of the work, would be listed first", "The professor decides the order without asking anyone else"], a: 2, x: "Le premier auteur est celui qui a fait le plus gros du travail, ici l'étudiant." } ] },
    { id: 'vza020', diff: 4, ctx: "Listen to a conversation between a doctoral student and the director of graduate studies.", names: { W: "Student", M: "Director" }, lines: [
      ["W", "Thanks for finding the time, Professor Brandt. I wanted to, um, sort of float an idea, and I'd like it to stay between us for now, if that's all right."],
      ["M", "Of course. Though I should say I can't promise to forget it. What's on your mind?"],
      ["W", "It's about my research direction. I've been wondering whether, you know, the fit with my current advisor is as strong as it could be. Not that there's any, I mean, she's a brilliant scholar, and I've learned an enormous amount."],
      ["M", "But."],
      ["W", "But I think we have very different ideas about how a dissertation should evolve. She likes to see a finished chapter before discussing anything, and I tend to think out loud. We've, well, we've gone a couple of months without really meeting."],
      ["M", "I see. So what you're telling me, if I'm reading it correctly, is that the working relationship has more or less stalled, and you'd like to know whether a change is possible without it turning into a scandal."],
      ["W", "I wouldn't put it quite that way, but, yes, essentially."],
      ["M", "Well, you needn't worry about the scandal part. Students change advisors more often than anyone admits, and it's usually handled as a matter of fit rather than fault. What matters is that you do it before you've invested another year."],
      ["W", "Would I have to explain my reasons to her?"],
      ["M", "Eventually, yes, though not in a way that has to be adversarial. I'd suggest first talking to the person you have in mind, since there's no point in raising it with your current advisor until someone has agreed to take you on."],
      ["W", "That makes sense. I hadn't even thought about the order."],
      ["M", "Most people don't. They think of it as a confrontation, when it's really a logistics problem with an emotional layer."]],
      qs: [
        { q: "What is the student's main purpose in meeting the director?", o: ["To complain formally about her advisor's behavior", "To ask for an extension of her dissertation deadline", "To request a different research topic for her dissertation", "To explore the possibility of changing her advisor"], a: 3, x: "Elle veut savoir si changer de directrice de thèse est possible, sans en faire un conflit." },
        { q: "What does the director mean by \"if I'm reading it correctly\"?", o: ["He has not understood what the student is trying to say", "He is putting her implied message into plain words", "He does not believe that the problem is serious", "He wants her to repeat what she said more clearly"], a: 1, x: "Il reformule explicitement ce qu'elle laisse entendre sans le dire : la relation de travail est au point mort." },
        { q: "What does the director advise about the order of the steps?", o: ["Tell her current advisor about her plan before speaking to anyone", "Speak to the scholar she would like to work with first", "Wait another year before taking any action about the situation", "Ask the graduate school to announce the change to the department"], a: 1, x: "Il ne sert à rien d'en parler à la directrice actuelle avant qu'un autre professeur ait accepté de la prendre." } ] },
    { id: 'vza021', diff: 4, ctx: "Listen to a conversation between a student and an associate dean.", names: { W: "Associate dean", M: "Student" }, lines: [
      ["M", "Thanks for seeing me. I've received the notice that I've been placed on academic probation, and, to be honest, I think the circumstances were a bit, um, extenuating."],
      ["W", "Walk me through them."],
      ["M", "Last spring I was ill for most of April and May. It was a, well, a pretty serious bout of mono, and I missed two midterms and basically all the finals. My grades kind of collapsed."],
      ["W", "I'm sorry. Did you see a doctor at the time?"],
      ["M", "I did, at the clinic near my parents' place, but I never asked for a note. I just assumed that, you know, I'd explain it afterwards."],
      ["W", "Mm. I see. Well, the appeals committee has been known to be receptive to documented circumstances."],
      ["M", "Documented. Right. So, without a note, I'm, what, out of luck?"],
      ["W", "I wouldn't go as far as to say that. Retroactive documentation is a tall order, but it's not unheard of. If the clinic can confirm the dates of your visits, that may be sufficient."],
      ["M", "Okay. And if they can't?"],
      ["W", "Then the committee would be asked to take your word for it, and committees, as a rule, are rather fond of paper."],
      ["M", "That sounds like a polite way of saying it won't work."],
      ["W", "It's a polite way of saying I'd call the clinic before you do anything else. The appeal is due in two weeks, and I'd prefer you submit it with a record of those visits attached."]],
      qs: [
        { q: "What is the student trying to do?", o: ["Argue that his placement on probation should be reconsidered", "Persuade the dean to cancel a course he has failed", "Request permission to retake the finals he missed", "Explain why he skipped meetings with his advisor"], a: 0, x: "Il conteste son placement sous probation académique en invoquant des circonstances atténuantes." },
        { q: "What does the associate dean mean by \"committees, as a rule, are rather fond of paper\"?", o: ["The committee prefers written appeals to oral ones", "The committee often loses documents students submit", "The committee is likely to want written evidence", "The committee will not read appeals that are too long"], a: 2, x: "Ironie : le comité aime les documents écrits, donc sans justificatif la demande sera fragile." },
        { q: "What does the associate dean advise the student to do first?", o: ["Write a much longer explanation of the nature of his illness", "Ask the clinic to confirm the dates of his visits", "Wait for the results of the committee's review before acting", "Request a meeting with each of the professors he missed"], a: 1, x: "Elle lui conseille d'appeler la clinique pour obtenir une trace de ses consultations." } ] },
    { id: 'vza022', diff: 4, ctx: "Listen to a conversation between a student and a professor about a literature review.", names: { M: "Professor", W: "Student" }, lines: [
      ["M", "Right, so I've been through your literature review. It's, um, comprehensive."],
      ["W", "Thank you! I tried to include everything that's been published on the topic since the nineties."],
      ["M", "I can tell. It's comprehensive in the way a phone book is comprehensive. Every name is there, and in the right order."],
      ["W", "Oh. So that's, that's not a compliment."],
      ["M", "It's half a compliment. You've clearly read everything, which is more than I can say for a lot of people at your stage. But a review isn't a catalogue. Right now I finish a paragraph knowing what each author found and not having the faintest idea what you make of any of it."],
      ["W", "I thought I was supposed to stay neutral at this point. Summarize first, and then add my own argument in the discussion."],
      ["M", "That's a very common misunderstanding, and, to be fair, some textbooks encourage it. In practice, the review is where you do the arguing. You're showing how the studies relate, where they conflict, and what they leave out. The gap you're going to fill should be visible by the end."],
      ["W", "So, organize by debate instead of by author."],
      ["M", "Yes. Three or four questions the field is fighting about, and the studies slotted underneath. I'm not saying you've read too much. I'm saying you've argued too little."],
      ["W", "Should I cut some of the sources?"],
      ["M", "Not necessarily. Some will just move to a footnote. But if a study doesn't help you make a point, I'd ask why it's in the main text."],
      ["W", "Okay. That's, um, a lot of rewriting, but I can see what you mean."]],
      qs: [
        { q: "What does the professor mean when he compares the review to a phone book?", o: ["It lists sources without organizing them around an argument", "It contains too many sources that are out of date", "It is easy to read but it contains too many factual errors", "It is arranged by topic instead of by the name of each author"], a: 0, x: "Un annuaire est exhaustif et bien ordonné, mais sans argument : liste de références sans synthèse." },
        { q: "What misunderstanding does the student have?", o: ["She thinks a review should include only publications from the last few years", "She believes the discussion section of a paper is completely optional", "She thinks a review should stay neutral and leave the arguing for later", "She thinks every source she read must be mentioned in the main text"], a: 2, x: "Elle croit devoir résumer d'abord et argumenter dans la discussion, alors que c'est dans la revue de littérature qu'on argumente." },
        { q: "What does the professor suggest she do?", o: ["Reduce the number of years that the review covers", "Rewrite the review around the main debates in the field", "Replace most of the summaries with direct quotations from the authors", "Ask other students to read the review before she revises it"], a: 1, x: "Organiser par débats plutôt que par auteur." } ] },
    { id: 'vza023', diff: 4, ctx: "Listen to a conversation between a student and his faculty mentor.", names: { W: "Mentor", M: "Student" }, lines: [
      ["M", "I have two offers, and I'm, honestly, I'm paralyzed. A doctoral place here, fully funded, and a job at a consulting firm that pays about three times what the stipend does."],
      ["W", "Ah, the grand academic tradition of earning very little in order to know a great deal."],
      ["M", "That's, yeah, that's more or less my problem."],
      ["W", "I'm teasing, but only partly. Tell me, why a PhD? Not why it's respectable, but why you."],
      ["M", "I loved the research I did with you. And I'm good at it, I think. And I'm not sure I want to spend the next ten years optimizing client presentations."],
      ["W", "Those are three different reasons, and only two of them are reasons to do a doctorate. The last one is a reason to avoid consulting, which is different."],
      ["M", "You think I'm using the PhD to escape?"],
      ["W", "I think a lot of people drift into doctorates because they can't decide, and the program is a very comfortable place to postpone deciding. For some, that works out. For many, five years later they're older, poorer, and still undecided."],
      ["M", "That's bleak."],
      ["W", "It isn't meant to be. Here's the question I'd ask. If the stipend and the salary were the same, which would you pick?"],
      ["M", "The PhD. Without hesitation, actually."],
      ["W", "Then there's your answer, or at least most of it. The gap in pay is real, but it's a price, not a verdict. Just be sure you're buying the thing you want, rather than avoiding the thing you fear."]],
      qs: [
        { q: "What is the student trying to decide?", o: ["Whether to take the consulting job or the doctoral place", "Which of two doctoral programs he should choose to join", "Whether to ask his mentor for a recommendation letter this week", "How to negotiate a higher salary with the consulting firm"], a: 0, x: "Un doctorat financé ou un poste en conseil mieux payé." },
        { q: "What is the mentor's attitude toward the student's reasons for wanting a PhD?", o: ["She believes none of his reasons is strong enough to justify a PhD", "She thinks that his reasons are all good ones and well prepared", "She feels he is overestimating his own ability to do original research", "She is concerned that one reason is really about avoiding something else"], a: 3, x: "Le troisième motif est une raison d'éviter le conseil, pas de faire un doctorat." },
        { q: "Why does the mentor ask, \"If the stipend and the salary were the same, which would you pick?\"", o: ["To test whether the difference in pay is really the issue", "To find out whether he understands the financial risks", "To make him see the difference in his earnings", "To persuade him to choose the higher-paid job"], a: 0, x: "Sa question isole le facteur argent : s'il choisit le doctorat à salaire égal, le salaire n'est pas le vrai obstacle." } ] },
    { id: 'vza024', diff: 4, ctx: "Listen to a conversation between a student and a university sustainability officer.", names: { M: "Officer", W: "Student" }, lines: [
      ["W", "I'll get straight to it. I'd like the university to ban disposable cups in all the campus cafés, starting next semester. I've got a petition with eight hundred signatures."],
      ["M", "Eight hundred is a good number. And I'm sympathetic, genuinely. But I'd be doing you no favors if I told you this would sail through."],
      ["W", "What's the obstacle? The cost?"],
      ["M", "Partly. But the real obstacle is that the cafés aren't run by the university. They're operated by outside contractors, and the contracts run until 2028. Any change to the cup policy means renegotiating, and the contractors will want something in return."],
      ["W", "So the university can't just decide?"],
      ["M", "It can, technically, in the sense that anyone can decide anything. It just can't do it cheaply, or quickly, or without a lot of people being annoyed."],
      ["W", "That sounds like a polite way of telling me to give up."],
      ["M", "Not at all. I'm telling you to change the proposal, not drop it. I've seen ambitious bans die in committee more often than I can count, whereas a pilot in one café, say the one in the library, for a semester, with data on how many cups are used? That has a way of surviving."],
      ["W", "A pilot feels so much smaller than what I was asking for."],
      ["M", "It is smaller, but it creates evidence, and evidence is what committees say they want when they're about to say no. If the numbers are good, you come back in a year and ask for the whole thing."],
      ["W", "And if the contractor refuses even a pilot?"],
      ["M", "Then at least you'll know where the resistance is, which is a more useful thing to know than you'd think."]],
      qs: [
        { q: "What is the main obstacle to the student's proposal?", o: ["The petition does not have enough signatures to be taken seriously", "The university has no money available to buy reusable cups", "The cafés belong to contractors who hold long-term contracts", "The sustainability office itself is opposed to the idea of a ban"], a: 2, x: "Les cafés sont gérés par des prestataires externes dont les contrats courent jusqu'en 2028." },
        { q: "What does the officer mean by \"It can, technically, in the sense that anyone can decide anything\"?", o: ["The university is not legally allowed to make this decision at all", "The university has the authority, but acting would be hard", "Students have the right to make this decision for themselves", "The officer believes that the decision has already been made"], a: 1, x: "Ironie : la décision est possible en théorie, mais elle serait coûteuse, lente et impopulaire." },
        { q: "Why does the officer recommend a pilot in one café?", o: ["It would be accepted by the contractors without negotiation", "It would produce evidence that could support a wider policy later", "It would satisfy the students who signed the petition", "It would prove to the committee that a ban cannot work"], a: 1, x: "Les chiffres du test fournissent des preuves pour demander l'interdiction complète plus tard." } ] },
    { id: 'vza025', diff: 4, ctx: "Listen to a conversation between a doctoral student and her supervisor in a biology lab.", names: { M: "Student", W: "Supervisor" }, lines: [
      ["M", "Do you have a minute? It's, uh, it's not urgent urgent, but I'd rather say it now than let it sit. I've been re-running the assays from the 2022 paper, the ones Daniel did before he left."],
      ["W", "And?"],
      ["M", "And I'm not getting the same numbers. The effect is there, but it's about half the size. I've checked my protocol three times, and I think the difference might be in his normalization step."],
      ["W", "Let's not get ahead of ourselves. Replications come out a bit smaller all the time. It doesn't mean anything is wrong."],
      ["M", "Maybe. But the paper's conclusion depends on the effect being large enough to explain the phenotype. If it's half the size, that explanation gets shaky."],
      ["W", "I'm aware of that, thank you."],
      ["M", "Sorry, I didn't mean to, I just, I don't know whether I'm supposed to raise this with anyone else."],
      ["W", "You're not. You've raised it with me, which is exactly right. Now give me something concrete. Can you send me his raw data and your own, side by side?"],
      ["M", "Sure. And if it turns out he made an error?"],
      ["W", "Then we write to the journal and publish a correction. A correction isn't a confession. It's what a lab does when it takes its own work seriously."],
      ["M", "I just worry about how it'll look for the lab. And for Daniel."],
      ["W", "It'll look much worse for everyone if someone else finds it in three years. Send me the files tonight, and let's talk on Thursday, once I've had a proper look."]],
      qs: [
        { q: "What did the student discover?", o: ["A former student's results were much weaker than the paper reported", "His own protocol contained a mistake that he had to correct", "A rival laboratory had published data that conflicted with the paper", "The journal had made an error when it printed the figures"], a: 0, x: "L'effet est de moitié moindre que celui publié, peut-être à cause de l'étape de normalisation de Daniel." },
        { q: "What does the supervisor imply by saying, \"I'm aware of that, thank you\"?", o: ["She is grateful that the student pointed out an unexpected problem", "She is irritated that the student is explaining something obvious", "She does not think the issue is relevant to the paper", "She wants the student to stop worrying about the paper"], a: 1, x: "Ton sec : elle connaît déjà les implications, ce que l'étudiant vient de lui expliquer." },
        { q: "What is the supervisor's attitude toward publishing a correction?", o: ["It should be avoided because it harms the reputation of the lab", "It is only necessary if another laboratory complains first", "It is unnecessary because replications often yield smaller effects", "It is what a lab does when it takes its own work seriously"], a: 3, x: "« A correction isn't a confession » : c'est ce que fait un laboratoire sérieux." } ] },
    { id: 'vza026', diff: 4, ctx: "Listen to a conversation between a student and a professor about the use of AI tools.", names: { W: "Student", M: "Professor" }, lines: [
      ["W", "Professor Osei, I wanted to ask something about the take-home exam. The instructions say we can't use AI tools, but, um, they don't really say what counts."],
      ["M", "That's a fair complaint, and several of you have raised it. What did you have in mind?"],
      ["W", "Well, I'm not planning to have it write my essay. But I do use it to, like, brainstorm, or ask it to explain a concept I didn't follow in the reading. And my English isn't perfect, so I run my sentences through a grammar checker."],
      ["M", "Okay. Let me try to explain where I draw the line, and you'll tell me if it's unreasonable. The exam is meant to test whether you can build an argument from the course material. Anything that does that thinking for you is off limits."],
      ["W", "So brainstorming is out?"],
      ["M", "Asking a chatbot to generate your thesis is out. Talking an idea through with a classmate is fine, and I'd say a tool that merely suggests a few angles falls somewhere in between. Which is exactly why I'd like you to disclose it."],
      ["W", "Disclose it how?"],
      ["M", "A short note at the end. Which tools, for what. I'm not going to penalize an honest note. What I'll penalize is a paper that sounds like no one in particular wrote it."],
      ["W", "And the grammar checker?"],
      ["M", "Fine, as long as it corrects and doesn't rewrite. Here's a test I use. If you can't explain every sentence in your paper without looking at the screen, it isn't yours, and I'd treat it that way."],
      ["W", "That's actually a clear way to put it. Thank you."]],
      qs: [
        { q: "Why does the student talk to the professor?", o: ["To ask permission to use an AI tool for the entire exam", "To find out which kinds of tool use are permitted on the exam", "To complain that the exam instructions are too strict", "To report that another student has used AI inappropriately"], a: 1, x: "Les consignes interdisent les outils d'IA sans préciser ce qui est visé." },
        { q: "What does the professor ask students to do about tools that fall between acceptable and unacceptable?", o: ["Avoid using any tool for the duration of the exam", "Tell him which tools they used and for what", "Ask classmates before using the tools", "Use only tools approved by the university"], a: 1, x: "Il demande une courte note de transparence ; une note honnête ne sera pas pénalisée." },
        { q: "What is the purpose of the professor's remark, \"If you can't explain every sentence in your paper without looking at the screen, it isn't yours\"?", o: ["To warn that he will question students orally after the exam is over", "To suggest that she should memorize every sentence in her paper", "To explain how the university detects the use of AI in take-home exams", "To give her a practical test for judging her own use of a tool"], a: 3, x: "C'est un critère pratique : si elle ne peut pas expliquer chaque phrase seule, le texte n'est pas le sien." } ] },
    { id: 'vza027', diff: 4, ctx: "Listen to a conversation between a student and an academic advisor about taking a leave of absence.", names: { W: "Advisor", M: "Student" }, lines: [
      ["M", "So here's the situation. A friend and I have a shot at getting into an accelerator for startups, and it starts in January. I'd need to take the spring semester off, but I figured it's just a gap semester. I'd come back in the fall."],
      ["W", "It might be, but I'd be careful with the word 'just.' Let me lay out what a leave of absence actually involves."],
      ["M", "Go ahead."],
      ["W", "First, your scholarship. It's paused while you're on leave, but the clock keeps running, so you'd lose a semester of eligibility. Second, your health insurance through the university ends the day your leave begins. And third, the housing guarantee only holds for students who are continuously enrolled."],
      ["M", "Wow. So it's not just a gap semester, it's a paperwork minefield."],
      ["W", "I'd put it less dramatically, but timing does matter. You have to file the formal leave request before the end of December. After that date, you're charged tuition for the whole spring semester whether you attend or not."],
      ["M", "End of December? That's only six weeks away."],
      ["W", "Which is why I'd start the form this week. The signatures from financial aid and housing take longer than people expect."],
      ["M", "Okay, I'll start on it. And the insurance?"],
      ["W", "You can buy a student plan for a semester at a reduced rate, if you apply before the leave begins. Don't let it lapse. A month without coverage can end up costing you more than the accelerator would pay you."],
      ["M", "Fair point. I'll look into it today."]],
      qs: [
        { q: "What does the student want to do?", o: ["Transfer to a different university in January", "Finish his degree a semester earlier than planned", "Take a semester off to join a startup program", "Find a part-time job to pay for his tuition"], a: 2, x: "Il veut prendre un semestre de congé pour intégrer un accélérateur de startups." },
        { q: "Why does the advisor say she would put his description \"less dramatically\"?", o: ["She agrees timing matters but finds his image exaggerated", "She thinks the paperwork is simple and requires no special care", "She wants to talk him out of taking any leave of absence at all", "She expects the scholarship rules to change before he returns"], a: 0, x: "Elle nuance « minefield » : il faut respecter les dates, mais ce n'est pas aussi risqué qu'il le dit." },
        { q: "What happens if the student files the leave request after December?", o: ["He is charged tuition for a semester he will not attend", "He is required to leave his university housing at once", "He loses his place in the accelerator program in January", "He forfeits his scholarship for the rest of his degree"], a: 0, x: "Après la date limite de fin décembre, il paierait la totalité des frais du semestre, même sans y assister." } ] },
    { id: 'vza028', diff: 4, ctx: "Listen to a conversation between a student and a professor about a required textbook.", names: { W: "Student", M: "Professor" }, lines: [
      ["W", "Professor Dunne, can I raise something about the textbook? The bookstore wants two hundred and forty dollars for the new edition, and a lot of us can't really afford that."],
      ["M", "Two hundred and forty. Yes. It's a marvelous invention, the new edition. Same content, different page numbers, and suddenly the entire used market is obsolete."],
      ["W", "So the previous edition would be okay?"],
      ["M", "That's the thing. I'm not allowed to say the old edition is just as good, for reasons I'll leave to your imagination. But I did put a copy of it on reserve in the library, and I've never been accused of stopping anyone from reading it."],
      ["W", "I did find a used copy online for thirty dollars. Would that be acceptable for the problem sets?"],
      ["M", "The problem sets are the sticking point. The exercises in the new edition have been reordered, and about a fifth of them are different. If you do the old exercises, you'll be doing problems I haven't assigned."],
      ["W", "Hmm. What if I made a table matching the old numbers with the new ones? I could share it with everyone using the old edition."],
      ["M", "Now that is an offer I'd be foolish to refuse. If you compile it, I'll post it on the course page and make a note that I'd rather not know how people got their copies."],
      ["W", "And the questions that were changed?"],
      ["M", "I'll email those as a supplement. It's the least I can do, given that I chose the book in the first place."],
      ["W", "Thank you. That helps a lot of people."],
      ["M", "Don't thank me too soon. You have a table to make."]],
      qs: [
        { q: "What problem does the student raise?", o: ["The textbook is not available in the campus bookstore at the moment", "The textbook contains too many errors in its exercises and examples", "The required textbook costs too much for many of the students", "The professor assigns more reading than students can finish"], a: 2, x: "Le manuel neuf coûte 240 $, ce que beaucoup d'étudiants ne peuvent pas payer." },
        { q: "What is the professor implying when he calls the new edition \"a marvelous invention\"?", o: ["He thinks it improved the course material a great deal", "He believes new editions exist mainly to kill the used-book market", "He wants students to buy it as soon as they possibly can", "He regrets that his own research is not included in the new edition"], a: 1, x: "Ironie : la nouvelle édition ne change presque rien mais rend le marché de l'occasion obsolète." },
        { q: "What agreement do the student and the professor reach?", o: ["The professor will arrange a discount on the new edition for the class", "The student will make a table matching old and new exercises", "The class will use only the old edition from now on", "The library will buy several extra copies of the new edition"], a: 1, x: "Elle fera un tableau de concordance ; il le publiera et enverra les exercices modifiés." } ] },
    { id: 'vza029', diff: 4, ctx: "Listen to a conversation between a prospective student and a graduate admissions officer.", names: { M: "Applicant", W: "Officer" }, lines: [
      ["M", "Thanks for taking my call. I wanted to ask about my application to the master's in finance. My undergrad transcript has one really bad semester, sophomore spring, and I'm not sure whether to explain it or just hope nobody notices."],
      ["W", "Hoping nobody notices has never been a reliable strategy. We read every transcript, and a sudden dip draws the eye."],
      ["M", "Right. So I should address it. But I don't want it to sound like I'm making excuses."],
      ["W", "There's a difference between an excuse and an explanation. An excuse says it wasn't my fault. An explanation says what happened, what I did about it, and what changed afterwards."],
      ["M", "My dad was in the hospital that semester. I was traveling home every weekend and I basically stopped studying."],
      ["W", "That's the kind of thing that belongs in the optional statement. Two or three sentences, no drama. And then, more importantly, point to the evidence that you recovered."],
      ["M", "My grades went back up the next semester, and I finished with a strong record in the quantitative courses."],
      ["W", "Good. We read for trajectory, not just for averages. A transcript with one bad term followed by steady improvement tells a better story than a flat one, frankly, though I'd not tell applicants to plan it that way."],
      ["M", "Ha. Understood. Should I get a recommendation to speak to it?"],
      ["W", "If a professor from that period can mention it, yes. But don't ask someone to write about your personal life. A short line about how you responded to difficulty is plenty."],
      ["M", "That's really helpful. I was worried I'd have to write a whole page."],
      ["W", "Please don't. A page would suggest you're still fighting about it."]],
      qs: [
        { q: "What is the applicant's main concern?", o: ["His recommendation letters might turn out to be too general", "He might have to explain a gap in his employment history", "His quantitative courses are not strong enough for the program", "He is unsure how to address one weak semester on his transcript"], a: 3, x: "Il hésite à expliquer son mauvais semestre de deuxième année." },
        { q: "According to the officer, what is the difference between an excuse and an explanation?", o: ["An explanation gives context and shows what the applicant did afterwards", "An explanation is shorter and avoids personal details", "An excuse is written by the applicant, while an explanation comes from a professor", "An excuse admits responsibility, while an explanation denies it"], a: 0, x: "Une explication dit ce qui s'est passé, ce qu'on a fait et ce qui a changé." },
        { q: "Why does the officer say, \"A page would suggest you're still fighting about it\"?", o: ["The committee will not read statements longer than a paragraph", "The statement is optional, so it should be skipped", "A longer explanation could contradict his recommendation letters", "A long statement may come across as defensive or unresolved"], a: 3, x: "Une longue justification donnerait l'impression qu'il n'a pas tourné la page." } ] }
  );

  CONTENT.talk.push(
    { id: 'tza001', diff: 2, g: 'W', ctx: "Listen to part of a lecture in a health science class.", text: "Most of us think of sleep as something we do when we're tired, but the timing of sleep is controlled by an internal clock. In humans, the master clock is a tiny cluster of neurons in the hypothalamus called the suprachiasmatic nucleus. It runs on a cycle of roughly twenty-four hours, which is where the term circadian rhythm comes from. Now, the clock isn't perfectly accurate on its own, so it needs to be reset every day, and the most powerful signal for that is light entering the eye. When darkness falls, the brain releases melatonin, a hormone that prepares the body for sleep. Morning light switches it off again. This system worked well for most of human history, but modern work has complicated things. Take people who work night shifts, such as nurses or factory workers. They are awake when the clock tells them to sleep, and they try to sleep when it tells them to be alert. Studies have found that long-term shift workers have higher rates of heart disease, diabetes, and digestive problems than people who work regular daytime hours. Researchers think the problem isn't only lost sleep. It's that the body's organs, which also follow daily cycles, get out of step with each other. So what can be done? Some hospitals now give night staff bright lights at the beginning of their shifts, and encourage them to wear dark glasses on the drive home, so that sunrise doesn't wake up the clock. Keeping a consistent sleep schedule, even on days off, also helps. Finally, a short nap before a night shift can reduce errors. None of this makes night work harmless, but it can make it a lot less damaging. For next class, please read the chapter on light and mood.",
      qs: [
        { q: "What is the lecture mainly about?", o: ["Why people need less sleep as they grow older and more tired", "How hospitals can schedule their nurses most efficiently each week", "Which hormones make people feel hungry at night when they work", "How the body clock shapes sleep and why night work harms health"], a: 3, x: "Le cours porte sur l'horloge interne et les risques liés au travail de nuit." },
        { q: "According to the professor, what is the most powerful signal for resetting the internal clock?", o: ["Light entering the eye each morning and evening", "The temperature of the bedroom at night", "The time of day at which a person eats", "The amount of exercise during the day"], a: 0, x: "« The most powerful signal for that is light entering the eye »." },
        { q: "Why does the professor say shift workers have more health problems?", o: ["They usually eat much more food than daytime workers do", "They are generally older and less fit than daytime workers", "They spend too many hours indoors during the daytime", "Their organs fall out of step with each other"], a: 3, x: "Le problème n'est pas seulement le manque de sommeil : les organes suivent des cycles quotidiens qui se désynchronisent." },
        { q: "Why might hospitals recommend dark glasses for night staff on the drive home?", o: ["To protect the eyes from the sun's glare while driving", "To help staff stay awake until they arrive home", "To prevent morning light from resetting the clock", "To reduce the production of melatonin before bed"], a: 2, x: "La lumière du matin remettrait l'horloge à l'heure du jour, ce qui empêche de dormir." },
        { q: "What does the professor imply about the strategies she mentions?", o: ["They remove the health risks of shift work completely", "They are too expensive for most hospitals to adopt", "They have not been tested on real workers", "They reduce the harm but do not eliminate it"], a: 3, x: "« None of this makes night work harmless, but it can make it a lot less damaging »." } ] },
    { id: 'tza002', diff: 3, g: 'M', ctx: "Listen to part of a lecture in a microbiology class.", text: "People often say that bacteria 'become resistant' to antibiotics, as if each cell learned to cope. That's a bit misleading. What really happens is selection. Within any large population of bacteria, a few individuals carry a mutation that lets them survive a given drug. Apply the antibiotic, and the susceptible majority die, while the rare survivors multiply into the space left behind. Evolution, in other words, is working on a timescale of hours. Now, if this were the whole story, resistance would be a local affair, arising separately in each species. But bacteria have a trick that makes the problem far more serious: they trade genes. Many resistance genes sit on small, circular pieces of DNA called plasmids, and bacteria can pass these plasmids to their neighbors, sometimes even to a different species. So a gene that arose in a harmless gut bacterium can end up in a pathogen in a hospital ward, without a single mutation along the way. Biologists call this horizontal gene transfer, to distinguish it from the vertical kind, from parent to offspring. It helps explain why resistance has spread so much faster than anyone predicted when penicillin first came into use. What turns this into a crisis is how often we apply the selective pressure. Hospitals use antibiotics heavily, and in many countries a great deal of the supply goes to livestock, often to promote growth rather than to treat illness. Each exposure favors the resistant strains. You may have been told always to finish a prescribed course, and for years that was standard advice. Some researchers now question whether longer courses really do prevent resistance, or whether shorter ones are enough. The evidence is still being sorted out, so I'd treat that rule with a bit more caution than your pharmacist might.",
      qs: [
        { q: "What is the main point of the lecture?", o: ["Antibiotics have stopped working against nearly every common infection", "Hospitals are the only place where resistant bacteria can arise today", "Livestock farming is the chief cause of all new bacterial diseases", "Resistance spreads by selection and by gene sharing between bacteria"], a: 3, x: "Sélection des survivants + transfert horizontal de gènes par les plasmides." },
        { q: "Why does the professor say the phrase \"become resistant\" is misleading?", o: ["Most bacteria are naturally resistant to every known antibiotic drug", "Bacteria become resistant only after they have been in contact with humans", "Resistance is caused mainly by patients taking too little medicine", "Individual bacteria do not adapt; the resistant ones survive and multiply"], a: 3, x: "Il s'agit de sélection de mutants rares, pas d'un apprentissage de chaque cellule." },
        { q: "What is horizontal gene transfer?", o: ["The passing of genes from parents to their offspring over generations", "A mutation that appears in many bacteria of one species at the same moment", "Gene movement between organisms that are not parent and offspring", "The loss of genes when a population of bacteria becomes smaller"], a: 2, x: "Le contraire du transfert vertical, de parent à descendant." },
        { q: "Why does the professor mention livestock?", o: ["To show that farm animals spread resistant bacteria faster than people do", "To argue that farmers should stop treating their sick animals altogether", "To give an example of antibiotic overuse that favors resistant strains", "To explain why bacteria living in the gut are harmless to humans"], a: 2, x: "L'usage massif chez le bétail exerce une pression sélective." },
        { q: "What is the professor's attitude toward the advice to always finish a course of antibiotics?", o: ["He believes it is dangerous and should be abandoned immediately", "He suggests that the advice may be less well supported than people think", "He thinks it is harmless but has no effect at all on resistance", "He insists that it remains the most reliable rule for patients"], a: 1, x: "Les preuves sont encore en cours d'examen : il recommande plus de prudence que son pharmacien." } ] },
    { id: 'tza003', diff: 4, g: 'W', ctx: "Listen to part of a lecture in a medical science class.", text: "Let me start with a result that sounds like a joke. In 2010, researchers gave patients with irritable bowel syndrome a bottle of pills, and told them, quite openly, that the pills contained no active ingredient. A control group received nothing. After three weeks, the patients taking the so-called honest placebo reported significantly more relief. It was widely reported as proof that placebos work even when you know they're fake. Now, I'd like you to be a little suspicious of that headline, and, more generally, of the phrase 'the placebo effect.' First, the outcome in this trial was self-reported symptom relief, and that is precisely the kind of measure placebos can influence: pain, nausea, fatigue. There's little evidence that placebos shrink tumors or lower cholesterol. Second, the sample was small, only eighty or so patients, and the participants had volunteered for a trial about 'mind-body self-healing,' which hardly makes them a neutral group. Third, and here's the part that gets lost: when a patient improves after taking a placebo, we can't automatically credit the pill. Many conditions fluctuate. People tend to seek treatment when their symptoms are at their worst, and then, by sheer statistical regression to the mean, they feel better regardless of what they swallow. That is why a no-treatment group matters so much, and why a placebo arm alone tells us surprisingly little. So what's actually in the 'placebo effect'? Expectation, certainly. Attention from a caring clinician, possibly. The ritual of treatment, perhaps. And a good deal of natural recovery and statistical noise in the mix. I'm not claiming placebos are worthless; I'm claiming that the label bundles together several different things, and the neat story we tell about mind over matter hides most of them.",
      qs: [
        { q: "What is the professor's main purpose in this talk?", o: ["To question how the placebo effect is usually interpreted by the public", "To show that placebos are more powerful than many active drugs", "To explain how doctors currently treat irritable bowel syndrome", "To describe how clinical trials recruit and pay their volunteers"], a: 0, x: "Elle invite à se méfier du titre accrocheur et du terme « placebo effect »." },
        { q: "Why does the professor mention that the trial used self-reported symptom relief?", o: ["To suggest that patients may have lied to the researchers on purpose", "To show that this trial lasted longer than most comparable trials", "To note that placebos can plausibly influence this kind of outcome", "To explain why many patients in the control group dropped out early"], a: 2, x: "Douleur, nausée, fatigue : des mesures subjectives que le placebo peut influencer, contrairement aux tumeurs ou au cholestérol." },
        { q: "What does the professor suggest about patients who feel better after taking a placebo?", o: ["Their improvement may partly reflect regression to the mean", "Their symptoms were probably imaginary from the very beginning", "They were more intelligent and motivated than the control group", "They would have improved even more with an active drug"], a: 0, x: "On consulte quand les symptômes sont au pire, puis ils reviennent vers la moyenne." },
        { q: "Why does the professor say a no-treatment group matters?", o: ["It makes the trial cheaper and easier for researchers to run", "It guarantees that all participants know exactly what they are taking", "It proves that the pills in the trial contain no active ingredient", "It lets researchers separate the pill's effect from natural improvement"], a: 3, x: "Sans groupe sans traitement, impossible de distinguer l'effet du placebo de l'évolution naturelle." },
        { q: "What does the professor imply in her last sentence?", o: ["She considers placebos to be harmful in clinical practice", "She finds the common explanation too simple to be useful", "She thinks the idea of mind over matter is entirely false", "She believes the public understands placebos very well"], a: 1, x: "Le terme regroupe plusieurs phénomènes et l'histoire simple de l'esprit sur la matière les cache." } ] },
    { id: 'tza004', diff: 2, g: 'M', ctx: "Listen to part of a lecture in a physics class.", text: "Your phone knows where you are because of a network of about thirty satellites orbiting twenty thousand kilometers above the Earth. Each satellite carries an atomic clock and constantly broadcasts the time. Your phone listens to at least four of these signals and works out how long each one took to arrive. Since the signals travel at the speed of light, a tiny error in timing becomes a big error in position. A clock that's off by just one microsecond, a millionth of a second, translates into about three hundred meters. So the clocks must be extremely accurate, and this is where Einstein comes in. According to special relativity, a moving clock ticks more slowly than a stationary one. The satellites are traveling at roughly fourteen thousand kilometers an hour, which makes their clocks lose about seven microseconds each day compared with clocks on the ground. But general relativity says something different about gravity. Clocks run faster where gravity is weaker. The satellites are far from Earth, so their clocks gain about forty-five microseconds a day. Put the two effects together and the satellite clocks run fast by about thirty-eight microseconds daily. That sounds negligible, but if nobody corrected it, GPS positions would drift by roughly ten kilometers a day, and the system would be useless within hours. Engineers handle this by setting the clocks to tick very slightly slow before launch, so that once in orbit they match time on the ground. It's one of the rare cases where an abstract theory has a direct effect on everyday life. Every time you ask your phone for directions, you're relying on relativity.",
      qs: [
        { q: "What is the main topic of the lecture?", o: ["How satellites are launched into orbit", "Why atomic clocks are more accurate than other clocks", "How phones receive signals in large cities", "How relativity makes satellite navigation possible"], a: 3, x: "Les corrections relativistes sont indispensables au GPS." },
        { q: "Why must the satellite clocks be extremely accurate?", o: ["The signals travel more slowly than light through the atmosphere", "Phones can only receive one satellite signal at a time", "A tiny timing error would turn into a large position error", "The satellites change position every few minutes in the sky"], a: 2, x: "Une microseconde d'erreur correspond à environ 300 mètres." },
        { q: "According to the professor, why do the satellite clocks gain time because of gravity?", o: ["The satellites are traveling at very high speed around the Earth", "Gravity is weaker at their altitude than it is on the ground", "Atomic clocks react strongly to temperature changes in space", "The satellites are closer to the Sun than to the Earth"], a: 1, x: "La relativité générale : les horloges avancent plus vite là où la gravité est plus faible (+45 microsecondes)." },
        { q: "What do the engineers do to compensate for the difference?", o: ["They reset every satellite clock by hand once each day", "They set the clocks to run a little slow before the launch", "They send the correct time to every phone from ground stations", "They keep ground clocks that run slightly faster than normal"], a: 1, x: "Les horloges sont réglées légèrement plus lentes avant le lancement." },
        { q: "What can be inferred from the professor's final comment?", o: ["Most people do not really trust navigation systems anyway", "Einstein himself designed the first satellite navigation system", "Abstract physics can have practical uses in daily life", "Relativity matters only for devices that are located in space"], a: 2, x: "Il illustre qu'une théorie abstraite a un effet direct sur la vie quotidienne." } ] },
    { id: 'tza005', diff: 3, g: 'W', ctx: "Listen to part of a lecture in an energy technology class.", text: "For about sixty years, almost every solar panel on the market has been made of silicon. It works well, but it takes a lot of energy and high temperatures to produce. Over the last decade, a family of materials called perovskites has made the field rather excited. The name refers to a particular crystal structure, and the best-known solar versions contain lead and a halide such as iodine. What makes them attractive is how easy they are to make. You can dissolve the ingredients in a liquid, spread it on a surface, and let it dry at low temperature, a bit like printing. That suggests cheaper, lighter, even flexible panels. And the progress has been astonishing. In 2009, a perovskite cell converted under four percent of sunlight into electricity. Today, laboratory cells exceed twenty-five percent, which is a pace silicon needed decades to match. So why aren't rooftops covered with them? Well, there are problems. The first is durability. A silicon panel is guaranteed for twenty-five years or more. Perovskites tend to degrade when exposed to moisture, heat, and even light, and many early cells lasted only hours or days. Researchers have improved this with better compositions and protective coatings, but there's a gap between a record cell the size of a fingernail and a large panel that survives twenty years of weather. The second concern is the lead, which is toxic, though the quantities are small and the debate is about leakage and recycling rather than everyday risk. A more realistic near-term path may be to combine perovskite and silicon in a layered tandem cell, with each material capturing a different part of the spectrum. That approach has already pushed laboratory efficiency beyond what silicon can reach alone, and it avoids asking perovskites to prove themselves entirely on their own.",
      qs: [
        { q: "What is the main idea of the lecture?", o: ["Silicon solar panels will soon be replaced by an even cheaper material everywhere", "Laboratory records are the most reliable guide to commercial success", "Perovskites look promising for solar cells but face real obstacles", "Lead is the best material for making very efficient solar cells"], a: 2, x: "Matériau prometteur mais obstacles de durabilité et de toxicité." },
        { q: "What advantage of perovskites does the professor describe?", o: ["They already last longer than silicon panels in outdoor conditions", "They keep working efficiently without any direct sunlight at all", "They can be made from a liquid at low temperature", "They are completely free of toxic materials and easy to recycle"], a: 2, x: "Dissoudre les ingrédients, étaler, laisser sécher : comme une impression." },
        { q: "Why does the professor mention a cell \"the size of a fingernail\"?", o: ["To show that perovskites need very little sunlight to work well", "To explain how lead is kept out of the environment in the lab", "To contrast lab records with the challenge of full-size panels", "To illustrate that small cells are cheaper than large panels"], a: 2, x: "Il y a un fossé entre une cellule record minuscule et un grand panneau durable." },
        { q: "How does the professor describe the concern about lead?", o: ["It is the main reason perovskites are not yet sold", "It is manageable; the debate concerns leakage and recycling", "It is a serious daily danger to people near panels", "It is a problem that appears only in the laboratory"], a: 1, x: "Petites quantités : le débat porte sur les fuites et le recyclage." },
        { q: "Why might a tandem cell be a realistic near-term option?", o: ["Perovskite cells could then be tested without any silicon at all", "It is cheaper to produce than an ordinary silicon cell", "It does not ask perovskites to prove themselves alone", "It removes the need for protective coatings on the perovskite"], a: 2, x: "Chaque matériau capte une partie du spectre, et la durabilité du silicium rassure." } ] },
    { id: 'tza006', diff: 4, g: 'M', ctx: "Listen to part of a lecture in an environmental economics class.", text: "In 1865, the English economist William Stanley Jevons made an observation that must have seemed perverse. Britain's steam engines had become far more efficient, and yet the country's coal consumption was climbing, not falling. His explanation was that when a resource gets cheaper to use, people find more uses for it. This is now called the Jevons paradox, or, in more measured terms, the rebound effect. Let me separate the layers. A direct rebound occurs when you respond to a more efficient device by using it more. You replace your car with one that does better mileage, and, since driving is now cheaper, you drive a little further. Empirical estimates for household heating and driving tend to fall somewhere between ten and thirty percent, which means that a good part of the expected saving does materialize. Then there's the indirect rebound: the money you save gets spent on something else, a flight, say, which has its own footprint. Finally, at the level of the whole economy, cheaper energy services can make entire industries viable that weren't before. Lighting is the textbook case. As light became cheaper per unit, we simply began using astronomically more of it. The empirical picture is contested, and I'd warn you against two lazy conclusions. One is the cheerful assumption that efficiency will save us, which treats every engineering gain as a straight subtraction from emissions. The other is the fashionable cynicism that efficiency is pointless because the savings always vanish. Neither follows from the evidence. What the rebound effect does show is that efficiency standards, on their own, are a leaky instrument. If you want total consumption to fall, you generally need something that raises the price of the resource or caps its use, so that the savings aren't simply recycled into more of the same.",
      qs: [
        { q: "What is the professor's main purpose?", o: ["To describe a weakness in relying on efficiency alone", "To prove that more efficient technology always increases energy use", "To trace the history of the coal industry in Britain", "To compare the energy use of households with that of industries"], a: 0, x: "L'effet rebond montre que l'efficacité seule est un instrument « leaky »." },
        { q: "What does the professor say about direct rebound estimates for heating and driving?", o: ["They are close to zero for most households that were studied", "They suggest that much of the expected saving still happens", "They show that all of the expected saving disappears at once", "They are impossible to measure with any accuracy at all"], a: 1, x: "Dix à trente pour cent : une bonne part de l'économie attendue se réalise." },
        { q: "Why does the professor use lighting as an example?", o: ["It shows that new technology is usually rejected by the public at first", "It proves that rebound effects are always small in the long term", "It explains why coal was replaced by electricity in homes", "It shows how cheaper energy services can lead to far greater use"], a: 3, x: "Quand la lumière est devenue moins chère, on en a utilisé beaucoup plus." },
        { q: "What does the professor mean by \"the cheerful assumption that efficiency will save us\"?", o: ["The hope that new inventions will eventually make energy free", "The idea that consumers care more about the environment than about cost", "The opinion that governments should stop regulating energy use", "The belief that engineering gains turn directly into lower emissions"], a: 3, x: "Une hypothèse naïve qui traite chaque gain technique comme une simple soustraction aux émissions." },
        { q: "What does the professor suggest is needed to reduce total consumption?", o: ["Something that raises the price of the resource or limits its use", "More research into improving the efficiency of engines", "A voluntary agreement among the largest energy companies", "A ban on every product that uses a great deal of energy"], a: 0, x: "Un prix plus élevé ou un plafond, pour que les économies ne soient pas recyclées." } ] },
    { id: 'tza007', diff: 2, g: 'W', ctx: "Listen to part of a lecture in an environmental science class.", text: "Let's talk about permafrost. Permafrost is ground that stays frozen for at least two years in a row, and in places like Siberia, Alaska, and northern Canada it can be hundreds of meters deep. For thousands of years, dead plants and animals have been frozen into this soil before they could fully decay. As a result, permafrost holds an enormous amount of carbon, estimated at about one and a half trillion tons, which is roughly twice as much as the entire atmosphere contains. Now, the Arctic is warming about three to four times faster than the global average, and the frozen ground is starting to thaw. When it does, microbes wake up and begin to decompose the organic matter. Depending on whether the thawed soil is dry or waterlogged, they release carbon dioxide or methane. Methane is less abundant, but over a period of twenty years it traps far more heat than carbon dioxide does. This creates what scientists call a feedback loop: warming thaws the permafrost, thawing releases greenhouse gases, and those gases cause further warming. Some of the changes are visible. In certain areas the ground collapses as ice within it melts, forming new lakes and craters. Buildings, roads, and pipelines that were built on solid ground are cracking and sinking, and some Arctic villages are already facing costly repairs. How much carbon will actually be released is still uncertain. Most projections suggest a gradual release over many decades rather than a sudden burst, but a few studies warn that abrupt thaw could add more than we expect. What is clear is that permafrost carbon isn't included in most national emissions targets, so even if countries meet their goals, the Arctic could still add to the problem. That's why monitoring it closely matters.",
      qs: [
        { q: "What is the lecture mainly about?", o: ["How scientists measure the depth of frozen ground", "Why Arctic villages are being abandoned", "How the burning of fossil fuels is changing the Arctic", "Why thawing permafrost could add to global warming"], a: 3, x: "Le dégel libère du carbone qui accélère le réchauffement." },
        { q: "According to the lecture, why does permafrost contain so much carbon?", o: ["Volcanic activity in the Arctic released carbon into the soil", "Microbes in cold soil produce large amounts of carbon", "Plant and animal remains froze before they could decompose", "Glaciers carried carbon dioxide down into the ground"], a: 2, x: "Les restes végétaux et animaux ont gelé avant de se décomposer." },
        { q: "Why does the professor mention methane?", o: ["It is produced only when the thawed soil is completely dry", "It traps far more heat than carbon dioxide over twenty years", "It is released in much larger amounts than carbon dioxide", "It is the main cause of the collapse of the ground"], a: 1, x: "Moins abondant, mais plus puissant à vingt ans." },
        { q: "What is the feedback loop that the professor describes?", o: ["Warming thaws permafrost, and the gases released cause more warming", "Melting ice raises sea levels, and higher seas melt more ice", "Methane is absorbed by new lakes, which lowers the temperature", "Cracked buildings give off heat that thaws the ground beneath them"], a: 0, x: "Réchauffement, dégel, gaz à effet de serre, réchauffement supplémentaire." },
        { q: "What does the professor say about the national emissions targets?", o: ["They are too low to prevent any thawing from happening", "They are decided by the Arctic communities themselves", "They usually leave out the carbon released from thawing ground", "They already allow for sudden releases of methane in their estimates"], a: 2, x: "Le carbone du pergélisol n'est pas inclus dans la plupart des objectifs." } ] },
    { id: 'tza008', diff: 3, g: 'M', ctx: "Listen to part of a lecture in a computer science class.", text: "Suppose I give you ten data points and ask you to fit a curve through them. If I let you use a polynomial with ten adjustable coefficients, you can hit every single point perfectly. The error on your data is zero. Fantastic, right? Except that if I now give you a new point drawn from the same process, your wiggly curve will probably miss it by a mile. That, in a nutshell, is overfitting. The model hasn't learned the underlying pattern; it has memorized the noise in the particular sample it saw. Machine learning is full of this problem, because modern models often have millions of adjustable parameters, which is plenty of capacity to memorize a dataset. So how do we detect it? The standard approach is to hold some data back. You train on one portion, and you measure performance on a portion the model has never seen. If accuracy on the training set is excellent and accuracy on the held-out set is mediocre, you have a gap, and the gap tells you the model is memorizing rather than generalizing. There are several remedies. You can collect more data. You can simplify the model. You can add a penalty for complexity, which is known as regularization. Or you can use cross-validation, which repeats the train-and-test procedure on several different splits so you aren't fooled by one lucky division. But there's a subtler trap, which is that the held-out data must be genuinely independent. There's a frequently cited example from medical imaging in which a system appeared to diagnose a disease well, but it turned out to be picking up on features of the scanner or the hospital that happened to correlate with the diagnosis. It performed beautifully on data from that hospital, and badly elsewhere. A good test score, in other words, is only as trustworthy as the way the test was set up.",
      qs: [
        { q: "What is the main topic of the lecture?", o: ["Why a model that fits its training data perfectly can fail on new data", "How to choose the most powerful computer for machine learning work", "How polynomial equations are used to diagnose disease in medicine", "Why machine learning models need so many millions of parameters"], a: 0, x: "Le surapprentissage : mémoriser le bruit au lieu du motif sous-jacent." },
        { q: "What does the polynomial example illustrate?", o: ["A flexible curve can match the sample exactly yet miss new data", "A simple curve always fits data better than a complex curve does", "A model needs at least ten data points before it can work", "A model with zero error on its data is always accurate"], a: 0, x: "Dix coefficients pour dix points : erreur nulle sur l'échantillon, mais mauvaise prédiction ailleurs." },
        { q: "How does a researcher usually detect overfitting?", o: ["By checking whether the model contains millions of parameters", "By asking several experienced people to read through the model's code", "By comparing training performance with performance on unseen data", "By increasing the amount of random noise added to the data"], a: 2, x: "Un écart important entre les deux performances révèle la mémorisation." },
        { q: "What is the purpose of the medical imaging example?", o: ["To show that hospitals rarely agree to share their patient data", "To argue that scanners should all be standardized in every hospital", "To show that test scores can mislead if the test is not independent", "To prove that regularization always prevents this kind of error"], a: 2, x: "Le système s'appuyait sur des caractéristiques du scanner ou de l'hôpital, corrélées au diagnostic." },
        { q: "What does the professor imply in his final sentence?", o: ["Test scores are almost never useful for judging machine learning models", "Researchers should report only the accuracy on the training data", "Very large datasets always guarantee that a model will work well", "The way a test is designed matters as much as the score it produces"], a: 3, x: "Un bon score n'a de valeur que si le protocole de test est fiable." } ] },
    { id: 'tza009', diff: 4, g: 'W', ctx: "Listen to part of a lecture in a microbiology class.", text: "Fecal microbiota transplantation, which, yes, is exactly what it sounds like, has become one of the more remarkable stories in modern medicine. For patients with recurrent Clostridioides difficile infection, a bacterial gut disease that keeps returning after antibiotics, transplanting stool from a healthy donor cures the infection in a large majority of cases, in many trials above eighty percent. That is considerably better than another round of antibiotics. And the logic is persuasive. The antibiotics have wiped out the protective community of gut bacteria, so the pathogen takes over, and restoring that community crowds it out again. Now comes the part where I'd ask you to slow down. Success in one narrowly defined condition has encouraged enormous speculation about everything else. You'll read that the microbiome influences obesity, depression, autism, even how we respond to cancer drugs. Some of these links are real, in the sense that the bacteria in people with a condition differ from the bacteria in people without it. But a difference is not a cause. Illness changes diet, medication, and activity, all of which change the gut, so the arrow could easily point the other way. The experiments people cite most often involve germ-free mice, which receive bacteria from obese or lean donors and then change accordingly. Those are suggestive, but mice are not people, and a mouse with no microbes of its own is a rather peculiar experimental animal. Human trials of transplants for conditions beyond C. difficile have, so far, produced modest and inconsistent results. There are also practical concerns, such as the difficulty of screening donors and the risk of passing on unrecognized pathogens. So the fair summary, I think, is this: a remarkably effective treatment for one disease, and a great deal of confident speculation about the rest. The field is young, and it deserves patience more than slogans.",
      qs: [
        { q: "What is the professor's main point about fecal transplants?", o: ["They have been shown to cure depression and obesity in several clinical trials", "They are too dangerous to be used in any clinical setting at all", "They work only in laboratory mice and never in human patients", "They work well for one infection, but other claimed benefits are unproven"], a: 3, x: "Efficacité remarquable pour C. difficile, mais beaucoup de spéculation pour le reste." },
        { q: "According to the professor, why does a transplant work against the infection?", o: ["It kills the pathogen directly with powerful chemicals in the stool", "It restores the protective bacteria that crowd out the pathogen", "It makes the immune system stop reacting to the pathogen", "It supplies a different antibiotic that acts more slowly but safely"], a: 1, x: "Les antibiotiques ont détruit la flore protectrice ; la restaurer évince le pathogène." },
        { q: "What does the professor mean by \"a difference is not a cause\"?", o: ["Differences in gut bacteria are too small to measure accurately", "A condition might change the gut bacteria instead of being caused by them", "Researchers have not found any differences in the microbiomes of ill and healthy people", "The causes of illness can never be identified"], a: 1, x: "La flèche peut aller dans l'autre sens : la maladie modifie le régime, les médicaments et donc l'intestin." },
        { q: "Why does the professor call a germ-free mouse \"a rather peculiar experimental animal\"?", o: ["Such mice live much longer than ordinary laboratory mice do", "Such mice may not respond to bacteria as a normal body would", "Such mice are extremely difficult and expensive to obtain", "Such mice cannot be given bacteria taken from human donors"], a: 1, x: "Une souris sans microbes propres n'est pas représentative : remarque ironique sur les limites des études." },
        { q: "What can be inferred about the professor's view of the microbiome field?", o: ["She thinks it should stop receiving research funding", "She believes its main claims have all been disproven", "She is hopeful about the field but wants more careful evidence", "She considers it too technical to explain to students"], a: 2, x: "« It deserves patience more than slogans »." } ] },
    { id: 'tza010', diff: 3, g: 'M', ctx: "Listen to part of a lecture in an ecology class.", text: "Consider a spring in a temperate forest. Oak trees burst into leaf. A few weeks later, caterpillars hatch and feed on the new leaves, and a few weeks after that, small insect-eating birds time their chicks to hatch just when the caterpillars are most plentiful. Each stage depends on the one before it, and each has evolved to follow a seasonal cue, such as temperature or day length. Ecologists call the study of such seasonal timing phenology, and the trouble is that different organisms don't respond to the same cues. As the climate warms, the oak leafs out earlier, and the caterpillars, which respond to temperature, follow suit. But many birds that migrate long distances cue on day length at their wintering grounds in Africa. Day length hasn't changed. So they arrive on schedule, to find that the peak of the caterpillars has already passed. This is called a trophic mismatch. In a well-known study of pied flycatchers in the Netherlands, populations declined most steeply in the areas where the caterpillar peak had advanced the most. The chicks starved, and fewer survived to breed. Now, I don't want to leave you with the impression that mismatch is inevitable everywhere. Some species are flexible: resident birds can shift their breeding date as they sense the temperature, and some migrants have begun to arrive a little earlier. There's also evidence that natural selection favors individuals that breed early, so the shift may happen across generations too. The real question is whether adaptation can keep pace with a climate that is changing this quickly. The record so far is mixed. Where food peaks are narrow and sharp, as with caterpillars, a small error is costly. Where food is available over a longer period, it matters much less.",
      qs: [
        { q: "What is the main topic of the lecture?", o: ["How oak trees survive when the winters become warmer", "How warming can throw the timing of food chains out of step", "Why caterpillars have become more common in European forests", "How migratory birds find their way across entire continents"], a: 1, x: "Le décalage trophique résulte de réponses différentes aux signaux saisonniers." },
        { q: "Why do long-distance migratory birds often fail to adjust to earlier springs?", o: ["They cannot digest the food that is available earlier in the spring", "They arrive too early in the forest and then leave again", "They can no longer find the forests where they used to breed", "They rely on day length, which is unchanged where they winter"], a: 3, x: "Ils se fient à la durée du jour en Afrique, qui n'a pas changé." },
        { q: "What happened to the pied flycatchers in the Netherlands study?", o: ["Their populations grew in areas where caterpillars were most abundant", "They stopped migrating to Africa and stayed in the Netherlands", "They began feeding their chicks on a different kind of insect", "They declined most steeply where the caterpillar peak came earliest"], a: 3, x: "Déclin le plus marqué là où le pic de chenilles avait le plus avancé." },
        { q: "Why does the professor say that mismatch is not inevitable everywhere?", o: ["Some species are able to adjust their timing to the warmer spring", "All migratory birds now arrive earlier than before", "Caterpillars no longer depend on oak leaves", "Temperatures have stopped rising in many forests"], a: 0, x: "Certaines espèces sont flexibles : oiseaux résidents, migrateurs plus précoces, sélection naturelle." },
        { q: "What does the professor imply about food sources that are available over a long period?", o: ["They are more badly affected by mismatch than short, sharp peaks", "A small error in timing is less likely to harm the birds that depend on them", "They are found only in the warmer regions of the world", "They are usually produced by oak trees rather than by caterpillars"], a: 1, x: "Si la nourriture est disponible longtemps, une petite erreur de calendrier coûte peu." } ] },
    { id: 'tza011', diff: 4, g: 'W', ctx: "Listen to part of a lecture in a computer security class.", text: "Almost everything you do securely online rests on a mathematical asymmetry. Public-key cryptography lets two parties who have never met establish a shared secret over an open channel, and it does so because certain problems are easy in one direction and fiendishly hard in the other. Multiplying two large prime numbers takes a moment; recovering those primes from the product, for numbers hundreds of digits long, is beyond any classical computer. That's the basis of RSA, and the elliptic-curve schemes that now protect most web traffic rely on a similar one-way difficulty. In 1994, Peter Shor showed that a sufficiently powerful quantum computer could solve both problems efficiently. The word 'sufficiently' is doing a lot of work there. Today's quantum machines have a few hundred or thousand noisy qubits, whereas breaking RSA would require millions of reliable ones, and nobody can say with confidence when, or whether, that will be built. Many experts put it a decade or more away. So why the urgency? Because of a strategy sometimes called 'harvest now, decrypt later.' An adversary can record encrypted traffic today, store it cheaply, and decrypt it whenever a quantum computer becomes available. For secrets that need to stay secret for decades, such as diplomatic cables or medical records, the danger is effectively already here. The response is post-quantum cryptography: new algorithms, mostly based on problems about high-dimensional lattices, that no known quantum algorithm solves efficiently. Standards bodies have recently approved the first of these. Two caveats. First, 'no known algorithm' is not a proof, and some promising candidates have been broken by classical attacks. Second, symmetric encryption, the fast kind used to protect the data itself, is far less vulnerable, because quantum computers merely halve its effective key length, which can be countered by using longer keys. So the sensible attitude is neither panic nor complacency, but a managed, unglamorous migration.",
      qs: [
        { q: "What is the main purpose of the lecture?", o: ["To explain why quantum computers will certainly be built within a decade", "To argue that online banking is no longer secure in any form", "To describe how a future technology threatens current encryption", "To compare the speed of classical computers with quantum computers"], a: 2, x: "La menace quantique sur la cryptographie à clé publique et la réponse post-quantique." },
        { q: "What does the professor mean by \"the word 'sufficiently' is doing a lot of work\"?", o: ["Quantum computers have already reached that level of power", "Shor's discovery in 1994 was later shown to be incorrect", "The power required is far beyond anything that exists today", "Quantum computers are already used to protect most encryption"], a: 2, x: "Ironie : la puissance requise (des millions de qubits fiables) est très loin de l'état actuel." },
        { q: "Why is \"harvest now, decrypt later\" a concern even if quantum computers are years away?", o: ["Quantum computers can read messages that were never encrypted", "Data recorded today could be decrypted once the machines exist", "Current encryption has already been broken by classical computers", "Companies are required to store all encrypted messages"], a: 1, x: "On peut enregistrer aujourd'hui des données chiffrées et les déchiffrer plus tard." },
        { q: "What is the first caveat about post-quantum algorithms?", o: ["They are not proven secure, and some candidates have been broken", "They are too slow to be used on ordinary mobile phones", "They have not yet been approved by any standards organization", "They are built on the same one-way problems as RSA itself"], a: 0, x: "« No known algorithm » n'est pas une preuve ; certains candidats ont été cassés par des attaques classiques." },
        { q: "What is the professor's overall attitude toward the quantum threat?", o: ["The threat is too distant to justify any action by organizations", "The threat already makes all current encryption completely worthless", "The threat is an exaggeration invented by researchers seeking funds", "Preparation should be steady, but there is no need for alarm"], a: 3, x: "« Neither panic nor complacency, but a managed, unglamorous migration »." } ] },
    { id: 'tza012', diff: 3, g: 'M', ctx: "Listen to part of a lecture in a chemistry class.", text: "Plants need nitrogen, and the air is about seventy-eight percent nitrogen, but plants can't use it in that form, because the two atoms in a nitrogen molecule are held together by one of the strongest bonds in chemistry. For most of history, farmers relied on manure, crop rotation with beans and clover, and, in the nineteenth century, imported guano from Pacific islands. Around 1909, Fritz Haber found a way to combine nitrogen from the air with hydrogen to make ammonia, using high pressure, high temperature, and a metal catalyst, and Carl Bosch scaled the process up for industry. Estimates suggest that roughly half of the nitrogen in the bodies of people alive today passed through a Haber-Bosch plant. In other words, the process underpins food for several billion people. But there is a price. The process is energy-hungry, using one to two percent of the world's energy supply, mostly from natural gas, which supplies the hydrogen and releases carbon dioxide in the process. And then there's what happens to the fertilizer in the field. Crops typically take up only around half of the nitrogen that is applied. The rest washes into rivers and eventually the sea, where it feeds algae. When the algae die and decompose, they use up the oxygen in the water, creating so-called dead zones, such as the large one that forms each summer in the Gulf of Mexico. Some of the nitrogen also escapes as nitrous oxide, a potent greenhouse gas. Now, nobody is seriously proposing to abandon synthetic fertilizer, because the alternative is mass hunger. The question is how to use it more wisely. Options include applying it more precisely, planting cover crops to hold nitrogen in the soil, and making ammonia with renewable electricity instead of natural gas. None of this is simple, but it is a rare case where chemistry created a problem and may yet help solve it.",
      qs: [
        { q: "What is the main idea of the lecture?", o: ["Ammonia production feeds billions but harms the environment", "Synthetic fertilizer should be banned as soon as possible everywhere", "Nitrogen is the most abundant element found inside plants", "Farmers no longer use manure or crop rotation in modern farming"], a: 0, x: "Le procédé Haber-Bosch nourrit des milliards de personnes mais a un coût environnemental." },
        { q: "Why can plants not use nitrogen directly from the air?", o: ["The bond holding the two nitrogen atoms together is extremely strong", "The air contains far too little nitrogen for plants to absorb", "Plants can take nitrogen up only when it is dissolved in water", "Nitrogen in the air is already mixed with hydrogen in a stable way"], a: 0, x: "La liaison entre les deux atomes d'azote est l'une des plus fortes en chimie." },
        { q: "According to the professor, what happens to much of the fertilizer applied to crops?", o: ["It is absorbed by weeds growing close to the crops", "It is stored in the soil and used by crops in later years", "It runs off into rivers and the sea, where it feeds algae growth", "It is converted back into nitrogen gas and returns to the air"], a: 2, x: "Environ la moitié est lessivée vers les rivières puis la mer, ce qui nourrit les algues." },
        { q: "Why does the professor mention the Gulf of Mexico?", o: ["It is the place where Haber and Bosch built their first factory", "It is the largest producer of synthetic ammonia in the world", "It is a region where cover crops are now widely used", "It is an example of a dead zone caused by nitrogen runoff"], a: 3, x: "Zone morte estivale résultant du ruissellement d'azote." },
        { q: "What does the professor imply by saying chemistry \"may yet help solve\" the problem?", o: ["Cleaner ways of making fertilizer could be developed", "Chemists have already completely eliminated the problem in practice", "Public opinion will change on its own without further research", "Natural gas will soon be replaced by manure on most farms"], a: 0, x: "Ammoniac produit avec de l'électricité renouvelable, par exemple." } ] },
    { id: 'tza013', diff: 4, g: 'M', ctx: "Listen to part of a lecture in a biostatistics class.", text: "In 1973, the University of California, Berkeley was sued for sex bias in graduate admissions. The raw numbers looked damning: around forty-four percent of male applicants were admitted, against roughly thirty-five percent of women. Then a statistician took the data apart, department by department. In most individual departments, women were admitted at rates equal to or slightly higher than men. How can that be? Because women had applied in greater numbers to the most competitive departments, where nearly everyone is rejected, whereas men applied more to departments with generous admission rates. The aggregate figure and the departmental figures told opposite stories. This reversal is known as Simpson's paradox, and it isn't a curiosity of admissions. A classic medical example involves two treatments for kidney stones. Treatment A had a higher success rate for small stones and for large stones, yet Treatment B appeared better overall. The reason is that doctors tended to give the more invasive Treatment A to the harder, larger cases, so its overall figure was dragged down by the difficulty of its patients, not by its quality. So which numbers should you trust, the aggregate or the subgroups? Students often want a rule, and the uncomfortable answer is that there isn't a purely statistical one. It depends on the causal story. In the kidney stone case, stone size affects both which treatment is chosen and whether it succeeds, so you should compare within sizes. But suppose the subgroup is something the treatment itself influences, such as a blood pressure reading taken after the drug was given. Splitting by that variable would distort the comparison. The data alone can't tell you which situation you're in. You need a model of how the data came about. That's why I tell you that statistics isn't a way of avoiding judgment. It's a way of making your assumptions explicit enough to be criticized.",
      qs: [
        { q: "What is the professor's main point?", o: ["Raw totals are always more reliable than figures for subgroups", "Statistical tests can prove whether a university is biased or not", "Most medical studies contain errors in their basic calculations", "What a table of grouped data means depends on how the data arose"], a: 3, x: "Le sens de l'agrégation ou de la stratification dépend du modèle causal." },
        { q: "Why did the Berkeley data show a lower overall admission rate for women?", o: ["Women submitted weaker applications than men in most departments", "Departments with high acceptance rates mostly rejected women", "The statistician had miscalculated the figures for each department", "Women applied more often to highly selective departments"], a: 3, x: "Les femmes postulaient davantage aux départements très sélectifs." },
        { q: "In the kidney stone example, why did Treatment B look better overall?", o: ["Treatment B was cheaper than Treatment A", "Treatment B was tested on more patients", "Treatment A was used on patients who had mild symptoms", "Treatment A was given more often to difficult cases"], a: 3, x: "Le traitement A, plus invasif, était attribué aux cas les plus difficiles." },
        { q: "Why does the professor mention a blood pressure reading taken after the drug was given?", o: ["To show that it is always better to ignore subgroups completely", "To argue that blood pressure is very hard to measure accurately", "To explain why splitting by some variables can distort a comparison", "To demonstrate that doctors often choose treatments carelessly"], a: 2, x: "Le sous-groupe est influencé par le traitement lui-même : le séparer fausserait la comparaison." },
        { q: "What does the professor mean by saying statistics makes assumptions \"explicit enough to be criticized\"?", o: ["Statistics replaces the need for human judgment in research", "The assumptions behind statistical methods are nearly always wrong", "Its assumptions can be examined and challenged by others", "Critics of statistics usually ignore what the data really show"], a: 2, x: "La statistique n'évite pas le jugement : elle rend les hypothèses visibles et donc critiquables." } ] },
    { id: 'tza014', diff: 3, g: 'W', ctx: "Listen to part of a lecture in a neuroscience class.", text: "Roughly eighty percent of people who lose a limb continue to feel it afterward, sometimes vividly. They may feel the fingers of an arm that is no longer there clenching, or pain in a foot that was amputated years ago. This is phantom limb sensation, and it has puzzled physicians since the sixteenth century. For a long time, the favored explanation concerned the nerves in the stump, which continue to fire. But in the 1990s, the neurologist V. S. Ramachandran proposed something more intriguing. The brain contains a map of the body surface, and in that map, the area representing the hand sits right next to the area representing the face. When the arm is lost, the hand region no longer receives input, and the neighboring face region seems to spread into it. Ramachandran reported patients who felt sensations in the phantom hand when he touched their cheek. This idea of cortical remapping became a textbook example of brain plasticity. He also developed a treatment, the mirror box, in which a patient places the intact hand beside a mirror so that its reflection appears where the missing hand would be. Moving the healthy hand creates the illusion that the phantom is moving freely, and some patients reported that their painful cramps eased. Now, here's where I want you to be careful. Later imaging studies found that in amputees, the brain region that used to represent the hand may still hold a detailed pattern of the missing hand, even decades after the loss. That suggests the old map isn't simply overwritten and that remapping alone can't explain phantom pain. Mirror therapy, meanwhile, has produced encouraging but mixed results in controlled trials. So we have a vivid explanation that has been challenged, and a cheap treatment whose benefits are real for some people and uncertain for others. That's not unusual in neuroscience, where compelling stories often outrun the data.",
      qs: [
        { q: "What is the lecture mainly about?", o: ["How artificial limbs can be connected to the human nervous system", "What causes lasting pain in people who have recently been injured", "Explanations for phantom limb sensations and challenges to them", "Why the brain stops responding to touch after an amputation"], a: 2, x: "Les explications du membre fantôme, de la plasticité corticale aux remises en question." },
        { q: "According to Ramachandran's idea, why might a patient feel the phantom hand when the cheek is touched?", o: ["The face area of the brain's map may spread into the hand area", "The nerves in the stump are physically connected to the face", "The patient has trained the brain to link the two body parts", "The cheek and the hand share the same pathways in the spinal cord"], a: 0, x: "La zone du visage, voisine de celle de la main, envahit la zone désafférentée." },
        { q: "How does the mirror box work?", o: ["It records the activity of the missing hand's nerves", "It shows the patient an image of the stump moving", "It blocks signals traveling from the stump to the brain", "It tricks the brain into seeing the phantom hand move"], a: 3, x: "Le reflet de la main saine donne l'illusion que la main fantôme bouge." },
        { q: "What did the later imaging studies suggest?", o: ["The old hand map may remain largely intact after amputation", "The face region never expands into the hand region", "Phantom sensations disappear in most people after a few years", "Mirror therapy is dangerous for patients with phantom pain"], a: 0, x: "La carte de la main peut persister, ce qui limite l'explication par le remaniement seul." },
        { q: "What does the professor imply in her closing comment?", o: ["Attractive explanations can be accepted before they are well tested", "Neuroscientists rarely test their ideas on real patients at all", "Cheap treatments are generally less effective than expensive ones", "Mirror therapy has been proven to be completely worthless"], a: 0, x: "« Compelling stories often outrun the data »." } ] },
    { id: 'tza015', diff: 4, g: 'W', ctx: "Listen to part of a lecture in a forest ecology class.", text: "You've probably encountered the 'wood wide web.' Trees in a forest, we're told, are linked by underground fungal networks through which they share food, warn each other about pests, and older 'mother trees' nurture their seedlings. It makes for wonderful documentaries. I'd like to separate what's well established from what has been, shall we say, embroidered. What's solid: most trees form partnerships with mycorrhizal fungi. The fungus colonizes the roots, extends the tree's reach for water and nutrients such as phosphorus, and receives sugars in return. That's textbook botany. Also solid: fungi can physically connect the roots of different trees, forming common networks. In the 1990s, Suzanne Simard used radioactive carbon to show that carbon could move between birch and fir seedlings through the soil, and that was a real contribution. Now, the shakier claims. Does the transfer matter ecologically? A carbon atom moving from one tree to another is not the same as a tree 'sharing' resources in a way that helps its neighbor survive. Much of the movement could be the fungus itself keeping the carbon, or simply diffusion along a gradient. Do trees favor their kin? Evidence is thin. Do they send distress signals through the network? A few lab experiments on small plants suggest chemical signals can pass, but they rarely demonstrate that the receiver benefits. A recent review of the field concluded that many popular statements have outpaced the data: most of the evidence comes from greenhouse pots, and field studies are rare. I find this episode instructive. The danger lies in the language. Words like 'communicate', 'nurture', and 'cooperate' import human intentions into a system where we've measured only the flow of molecules. The network may well matter, but showing that requires patient fieldwork, not metaphors.",
      qs: [
        { q: "What is the main purpose of the lecture?", o: ["To describe a popular idea and sort the evidence from exaggeration", "To prove that trees communicate with each other through fungal networks", "To explain in detail how fungi absorb nutrients from the soil", "To compare greenhouse experiments with fieldwork in forests"], a: 0, x: "Distinguer ce qui est établi de ce qui a été « embroidered »." },
        { q: "According to the professor, what is well established about mycorrhizal fungi?", o: ["They allow older trees to protect and feed their own seedlings", "They send chemical warnings between trees of different species", "They help trees obtain water and nutrients in exchange for sugars", "They are found only in the roots of birch and Douglas fir trees"], a: 2, x: "Partenariat classique : le champignon étend la portée des racines et reçoit des sucres." },
        { q: "What does the professor say about Simard's experiment?", o: ["It was real, but it shows less than popular accounts claim", "It showed that mother trees favor their own seedlings over others", "It was later proven to be completely mistaken by other researchers", "It showed that fungi do not connect the roots of different trees"], a: 0, x: "Elle a montré un transfert de carbone, mais pas qu'il bénéficie aux voisins." },
        { q: "Why does the professor mention that the evidence mostly comes from greenhouse pots?", o: ["To point out that results may not hold in natural forests", "To suggest that forests do not contain any fungal networks at all", "To show that greenhouse experiments are cheaper than fieldwork", "To argue that young plants are unable to absorb any carbon"], a: 0, x: "Peu d'études de terrain : on ne sait pas si cela vaut en forêt réelle." },
        { q: "What does the professor criticize about words like \"communicate\" and \"nurture\"?", o: ["They are too technical for the general public to understand", "They imply human intentions in a system of molecule flow", "They mean different things in different languages and cultures", "They are used mainly by scientists who oppose the whole theory"], a: 1, x: "Ces mots importent des intentions humaines là où seuls des flux de molécules ont été mesurés." } ] },
    { id: 'tza016', diff: 3, g: 'M', ctx: "Listen to part of a lecture in an engineering class.", text: "Every lithium-ion battery loses capacity over time, and it's worth understanding why, since this is what limits the life of a phone or an electric vehicle. Inside the cell, lithium ions shuttle back and forth between two electrodes as you charge and discharge. The first culprit is a thin film that forms on the negative electrode, called the solid electrolyte interphase. A small amount is useful, because it protects the electrode. But it keeps growing slowly, and every bit of it consumes lithium that can then no longer carry charge. Think of it as a tax on the battery's capital: small each year, but cumulative. The second culprit is lithium plating. If you charge too fast, especially when the battery is cold, lithium ions can't slot into the electrode quickly enough and instead deposit as metallic lithium on its surface. That lithium is lost to the cell, and in severe cases it grows into needle-like dendrites that can cause short circuits. Third, the positive electrode can crack with repeated expansion and contraction, particularly if the cell is regularly pushed to an extreme state of charge. All of these processes accelerate with heat. A battery sitting fully charged in a hot car degrades far faster than one kept at moderate charge in a cool room. That's the basis for the advice you've seen to avoid charging to a hundred percent unless you need the range, and to avoid letting the battery drain to zero. In practice, the news isn't as bad as people fear. Data from large vehicle fleets suggests that, on average, electric car batteries lose roughly one or two percent of their capacity a year, which means many outlast the warranty. Solid-state batteries promise longer lives and greater safety, but they come with their own manufacturing problems, so I'd treat the timelines in press releases with some skepticism.",
      qs: [
        { q: "What is the main topic of the lecture?", o: ["Why lithium-ion batteries gradually lose capacity", "How lithium is extracted from the ground", "How to repair a battery that no longer holds a charge", "Why electric vehicles are safer than petrol cars"], a: 0, x: "Les mécanismes de dégradation de la capacité." },
        { q: "Why does the professor compare the growing film on the negative electrode to a tax?", o: ["It is a small loss that builds up over time", "It is a cost that is paid once at the beginning", "It reduces the capital but benefits other parts of the battery", "It can be avoided by charging more slowly"], a: 0, x: "Petite perte annuelle, mais cumulative : le film consomme du lithium à chaque fois." },
        { q: "Under what condition is lithium plating most likely to happen?", o: ["When a battery is left unused for several months", "When a battery is stored at a low level of charge", "When a battery is charged quickly while cold", "When a battery is charged in a hot environment"], a: 2, x: "Charge rapide à basse température : les ions ne s'insèrent pas assez vite." },
        { q: "What does the professor say about heat?", o: ["It repairs the cracks that form in the positive electrode", "It is harmful only when the battery is completely empty", "It has less effect on the battery than the age of the cell", "It speeds up the processes that wear the battery out"], a: 3, x: "Tous ces processus s'accélèrent avec la chaleur." },
        { q: "What is the professor's attitude toward the claims about solid-state batteries?", o: ["He believes they will be available to consumers within a year", "He thinks they have already failed in practice and been abandoned", "He is wary of the dates companies announce", "He considers them more dangerous than conventional batteries"], a: 2, x: "Il traite les calendriers des communiqués de presse avec scepticisme." } ] }
  );
})();
